(window.TNQ=window.TNQ||[]).push({"terms":{"직동식":{"d":"압력 변화를 스프링과 다이어프램이 직접 받아 밸브를 움직이는 방식으로 응답이 빠르다.","r":["파일럿식"]},"파일럿식":{"d":"작은 파일럿 밸브로 주 밸브를 움직여 고압에서도 정밀하게 제어하는 방식.","r":["직동식"]},"희생양극":{"d":"배관보다 부식되기 쉬운 금속으로 만든 양극으로, 대신 소모되며 배관을 보호한다.","r":[]},"안전간격":{"d":"화염이 틈을 지나 바깥 가스로 번지지 않는 최대 틈의 간격.","r":["화염일주한계"]},"화염일주한계":{"d":"내압방폭 용기의 틈에서 화염이 밖으로 번지지 않는 최대 틈의 간격.","r":["안전간격"]},"폭굉":{"d":"연소 화염이 충격파와 함께 음속보다 빠르게 퍼지는 폭발.","r":[]},"점화원":{"d":"가연물에 불을 붙이는 열이나 불꽃 같은 에너지원.","r":[]},"폭발범위":{"d":"가연성 가스가 공기와 섞여 불이 붙으면 폭발할 수 있는 농도의 범위.","r":[]},"비열비":{"d":"정압비열을 정적비열로 나눈 값.","r":[]},"담금질":{"d":"강을 가열한 뒤 급히 식혀 경도와 강도를 높이는 열처리.","r":["뜨임","풀림"]},"뜨임":{"d":"담금질한 강을 낮은 온도로 다시 가열해 취성을 줄이고 인성을 높이는 열처리.","r":["담금질"]},"풀림":{"d":"강을 가열한 뒤 천천히 식혀 내부응력을 없애고 연하게 하는 열처리.","r":["담금질"]},"확산연소":{"d":"연료와 공기가 불꽃면에서 서로 퍼져 섞이며 타는 연소 방식.","r":["예혼합화염"]},"예혼합화염":{"d":"연료와 공기를 미리 섞은 뒤 태워 얻는 불꽃.","r":["확산연소"]},"신축이음":{"d":"배관이 온도 변화로 늘고 줄어드는 길이 변화를 흡수하는 이음.","r":[]},"착화온도":{"d":"외부 불씨 없이도 스스로 타기 시작하는 가장 낮은 온도.","r":[]},"공기비":{"d":"이론 공기량에 대한 실제로 공급한 공기량의 비.","r":[]},"최소점화에너지":{"d":"가연성 혼합가스에 불을 붙이는 데 필요한 가장 작은 에너지.","r":[]},"퍼지":{"d":"불활성가스로 설비 안의 가연성 가스나 산소를 몰아내는 작업.","r":[]},"등심연소":{"d":"심지를 통해 올라온 액체연료가 증발하며 타는 연소 방식.","r":[]},"계통오차":{"d":"측정 조건이 달라질 때 규칙적으로 생겨 참값에서 한쪽으로 치우치는 오차.","r":[]},"방사선투과시험":{"d":"방사선으로 용접부 속 결함을 찍어 보는 비파괴검사.","r":[]},"이론연소온도":{"d":"열손실 없이 이론 공기량으로 완전연소할 때 이르는 최고 온도.","r":[]},"방파판":{"d":"차량 탱크 안에서 액체가 출렁이는 것을 막는 판.","r":[]},"안전밸브":{"d":"설비 압력이 설정값을 넘으면 자동으로 열려 압력을 내보내는 밸브.","r":[]},"진발열량":{"d":"연료가 완전연소할 때 내는 열량에서 수증기의 증발잠열을 뺀 열량.","r":[]},"고정탄소":{"d":"석탄에서 수분, 휘발분, 회분을 뺀 나머지 탄소 성분.","r":[]},"아레니우스 법칙":{"d":"반응속도상수가 온도에 따라 지수적으로 변하는 관계를 나타내는 법칙.","r":[]}},"notes":{"0.707배나 1.412배가 아니다":"압력차가 변할 때 유량이 0.707배나 1.412배가 되는 것은 아닙니다.","1단 감압식보다 배관 압력손실을 크게 해도 된다":"분리형 자동절체식은 1단 감압식보다 배관 압력손실을 크게 잡아도 됩니다.","1일 석탄소비량에 의한 최대증발량도 아니다":"1일 석탄소비량으로 나타낸 최대증발량도 연소율이 아닙니다.","1회전에 0.5ℓ를 계량한다는 뜻이다":"미터가 한 바퀴 돌 때 0.5ℓ를 계량한다는 뜻입니다.","2.5MPa 이상 압축 시에는 희석제를 첨가한다":"압력이 2.5MPa 이상으로 오르는 압축에서는 희석제를 첨가해야 합니다.","2000℃는 매우 눈부신 흰색, 1000℃는 노란색이다":"물체가 2000℃에서는 매우 눈부신 흰색, 1000℃에서는 노란색으로 빛납니다.","20인 이상 아동복지시설과 지정 문화재 건축물도 제1종이다":"아동복지시설은 20인 이상이면, 그리고 지정 문화재 건축물도 제1종 보호시설입니다.","2차압력이 저하하면 유량이 늘고 구동압력이 오르면 유량이 줄어든다":"2차압력이 낮아지면 유량은 증가하고, 구동압력이 높아지면 유량은 감소합니다.","300m³ 이상일 때 운반책임자가 동승한다":"가연성 압축가스를 300m³ 이상 운반하면 운반책임자가 함께 탑니다.","30분 이상 동시 방사할 수 있는 수원에 접속한다":"물분무장치는 30분 이상 한꺼번에 방사할 수 있는 수원에 연결합니다.","350℃ 이하·9.8N/mm² 이하 압력 배관에 쓴다":"SPPS는 350℃ 이하, 9.8N/mm² 이하의 압력 배관에 씁니다.","35℃에서 0Pa 초과 액화가스는 액화시안화수소·액화브롬화메탄·액화산화에틸렌이다":"액화시안화수소, 액화브롬화메탄, 액화산화에틸렌이 35℃에서 0Pa을 넘는 액화가스입니다.","48시간 정치나 1일 2회 염화제1동 시험지는 기준이 아니다":"정치를 48시간으로 하거나 1일 2회 염화제1동 시험지로 검사하는 것은 기준이 아닙니다.","5m³ 이상의 가스를 저장하는 것에는 가스방출장치를 설치한다":"가스 5m³ 이상을 저장하는 설비에는 가스방출장치를 달아야 합니다.","65%·70% 이상이나 95% 미만은 기준이 아니다":"65%와 70% 이상, 95% 미만이라는 수치는 아세틸렌 용기 다공도 기준이 아닙니다.","99.5% 이상이며 35℃에서 11.8MPa 이상으로 충전한다":"산소의 품질검사 순도는 99.5% 이상이며 35℃에서 11.8MPa 이상으로 충전합니다.","ABC용 B-12 이상을 차량 좌우에 각각 1개 이상 둔다":"차량 좌우에 ABC용 B-12 이상 소화기를 각각 1개 이상 둡니다.","B등급은 0.5mm 초과 0.9mm 미만, C등급은 0.5mm 이하이다":"화염일주한계가 0.5mm 초과 0.9mm 미만이면 B등급이고, 0.5mm 이하이면 C등급입니다.","CO₂·SOx를 검출하지 못하고 물에 대한 감도가 좋지 않다":"이산화탄소와 황산화물은 FID로 검출할 수 없고, 물 성분에는 감도가 떨어집니다.","CO₂가 저온에서 탄소와 산소로 분리되거나 촉매 역할을 하지는 않는다":"CO₂가 저온에서 탄소와 산소로 갈라지거나 촉매로 작용하는 일은 없습니다.","CO₂는 배관을 폐쇄하므로 제거하고 수분은 건조기에서 제거한다":"CO₂는 배관을 막기 때문에 제거하고, 수분은 건조기에서 없앱니다.","CO₂를 30% KOH, 중탄화수소를 발연황산에 흡수시킨다":"헴펠식은 이산화탄소를 30% KOH에, 중탄화수소를 발연황산에 흡수시켜 분석합니다.","CO가 수소보다 넓은 것은 아니다":"CO의 폭발범위가 수소보다 넓다는 설명은 맞지 않습니다.","Cp＞Cv이고 Cp/Cv는 비열비이다":"정압비열이 정적비열보다 크고, 둘의 비 Cp/Cv가 비열비입니다.","H₂·He 등이 완전가스에 가까운 실제기체이다":"H₂와 He 같은 실제기체가 완전가스에 가깝습니다.","H₂S는 연당지(전분지 아님), CO는 염화파라듐지이나 적색 아님":"H₂S는 전분지가 아닌 연당지로 검지하고, CO는 염화파라듐지를 쓰지만 적색 변화는 아닙니다.","LNG 수입기지에서는 Open Rack Vaporizer(해수식)를 쓴다":"LNG 수입기지에서는 해수를 열원으로 쓰는 Open Rack Vaporizer를 씁니다.","LPG 설비 기밀시험에는 공기·탄산가스·질소를 쓴다":"LPG 설비 기밀시험에는 공기, 탄산가스, 질소를 시험용 가스로 씁니다.","LPG 압력조정기 제조에는 유량측정설비도 필요하다":"LPG 압력조정기를 만들 때는 유량측정설비도 갖추어야 합니다.","LPG 액체는 물보다 가볍고 기체는 공기보다 무겁다":"비중으로 보면 액체 LPG는 물보다 작고 기체 LPG는 공기보다 큽니다.","LPG 용기는 탄소강이며 C 0.33% 이하이다":"LPG 용기는 탄소강으로 만들며 탄소(C) 함량은 0.33% 이하입니다.","LPG 종류와 관계없이 한냉시에도 충분히 기화되고 조성이 일정하다":"강제기화기는 LPG 종류와 상관없이 추울 때도 충분히 기화시키고 조성이 일정합니다.","LPG 충전용기는 충전 질량의 1/2 이상이며 1/3이 아니다":"충전용기는 충전 질량의 1/2 이상 채운 용기이고, 1/3을 기준으로 삼지는 않습니다.","NH₃는 다량의 물, H₂S는 금속산화물·염화 제2철로 제독한다":"암모니아는 다량의 물로, 황화수소는 금속산화물이나 염화 제2철로 제독합니다.","NH₃는 폭발범위가 좁아 위험도가 가장 낮다":"암모니아는 폭발범위가 좁아 위험도가 가장 낮습니다.","P·I·D 동작이고 O 동작은 불연속동작이 아니라 해당 분류에 없다":"연속동작은 P·I·D 동작이고, O 동작은 불연속동작 분류에도 들지 않습니다.","R은 약 1.987cal/mol·K, 848kg·m/kmol·K이다":"기체상수 R은 1.987cal/mol·K 또는 848kg·m/kmol·K 정도의 값입니다.","R의 단위는 cal/mol·K와 kg·m/kmol·K 등이다":"기체상수 R은 cal/mol·K나 kg·m/kmol·K 같은 단위로 나타냅니다.","Submerged Conversion Vaporizer는 연소열로 가열하는 방식이다":"Submerged Conversion Vaporizer는 버너의 연소열로 물을 데우는 기화 방식이며 SCV라 줄여 부릅니다.","U자관을 이용하는 방법도 쓴다":"U자관을 쓰는 방법으로도 밀도와 비중을 잽니다.","kg/h·kg/s·Nm³/s·m³/s·ℓ/h 등이다":"유량은 kg/h, kg/s, Nm³/s, m³/s, ℓ/h 같은 단위로 나타냅니다.","kg/m³은 밀도 단위이고 m²/min은 유량 단위가 아니다":"밀도의 단위는 kg/m³이고, m²/min은 유량의 단위로 쓰이지 않습니다.","kg·m/kg·K나 kcal/kmol은 R의 단위가 아니다":"R의 단위로 kg·m/kg·K나 kcal/kmol은 쓸 수 없습니다.","n＝0은 등압, n＝1은 등온이고 단열이 아니다":"n이 0이면 등압, 1이면 등온 과정이며 단열 과정은 아닙니다.","ℓ/rev는 rev/ℓ이나 MAX 유량 표시와 다르다":"ℓ/rev 표시는 MAX 유량 표시와 다른 것입니다.","가공 중 결함이 생기지 않아야 하며 무게가 무겁지 않아야 한다":"가공하다가 결함이 생기면 안 되고, 재료가 무거워서도 안 됩니다.","가는 관 내부에서 화염이 꺼지는 한계의 직경이다":"가는 관 안에서 화염이 꺼지는 한계의 지름이 한계직경입니다.","가스가 통과하지 못하는 고장이다":"불통은 가스가 아예 통과하지 못하는 고장입니다.","가스는 통과하나 계량되지 않는 고장이다":"부동은 가스는 지나가는데 계량이 되지 않는 막식 가스미터의 고장입니다.","가스를 과다하게 공급하면 역화가 아니라 선화(리프팅)가 된다":"가스를 과다하게 공급해 불꽃이 버너에서 떨어지는 것은 역화가 아니라 선화(리프팅)입니다.","가스 명칭·내압시험압력·가열방식 및 형식을 표시한다":"특정설비에는 가스 명칭, 내압시험압력, 가열방식과 형식을 표시합니다.","가스미터 원격계측 방식은 기계식·펄스식·전자식이다":"가스미터 원격계측 방식에는 기계식, 펄스식, 전자식이 있습니다.","가스설비 누출·조업조건 변동·진동 및 이상음을 본다":"운전 중에는 가스설비 누출, 조업조건 변동, 진동과 이상음을 봅니다.","가스압 저하로 가스량이 극히 적을 때는 역화이다":"가스압이 낮아 가스량이 극히 적을 때 불꽃이 안으로 들어가는 것은 역화입니다.","가스연료는 역화 위험이 없고 조절범위가 크며 고온 예열이 가능하다":"가스연료는 불꽃이 되돌아갈 위험이 없고 조절 폭이 넓으며 미리 달궈 쓸 수도 있습니다.","가스온풍기와 배기통은 나사식·플랜지식·밴드식 등으로 접합한다":"가스온풍기와 배기통은 나사식, 플랜지식, 밴드식 등으로 이어 붙입니다.","가스 유속을 거의 일정하게 하고 셀 주위 온도를 일정하게 유지한다":"측정 오차를 줄이려면 가스가 흐르는 속도와 셀 주변 온도를 한결같이 유지해야 합니다.","가스의 연소성을 판단하는 수치이다":"웨버지수는 가스의 연소성을 판단하는 수치입니다.","가스 치환·내부 가스분석·배관 차단을 한다":"수리 전에는 가스를 치환하고 내부 가스를 분석하며 배관을 차단합니다.","가압이나 습기 제거는 정전기 방지대책이 아니다":"가압하거나 습기를 없애는 것은 정전기를 막는 방법이 되지 못합니다.","가연물·산소공급원·점화원이다":"연소가 일어나려면 가연물, 산소공급원, 점화원이 있어야 합니다.","가연성 가스 검출기는 안전등형·간섭계형·열선형이고 광조사형은 아니다":"안전등형, 간섭계형, 열선형이 가연성 가스 검출기이고 광조사형은 해당하지 않습니다.","가연성 가스 공급 차단(제거)·냉각·질식으로 이루어진다":"소화는 가연성 가스 공급을 끊는 제거, 냉각, 질식으로 이루어집니다.","가연성가스는 연, 독성가스는 독 자를 표시한다":"가연성가스 용기에는 연, 독성가스 용기에는 독 자를 표시합니다.","가연성가스·독성가스·산소 용기는 각각 구분해 둔다":"가연성가스, 독성가스, 산소 용기는 종류별로 나누어 둡니다.","가연성가스 용기·탱크 내부는 제2종이 아니라 제0종 위험장소이다":"가연성가스를 담은 용기와 탱크 안쪽은 제0종 위험장소이며 제2종이 아닙니다.","가연성가스 운반 차량에는 분말소화기를 쓰고 포말·화학포는 쓰지 않는다":"가연성가스 운반 차량의 소화기는 분말소화기이고, 포말이나 화학포 소화기는 사용하지 않습니다.","가연성가스 전반을 검지하고 필라멘트 저항 증가를 검출한다":"접촉연소식 검지기는 가연성가스를 전반적으로 검지하며 필라멘트의 저항이 늘어나는 것을 검출합니다.","가연성물질 제거·조연성물질 차단·발화원 소거가 방지 원리이다":"가연성물질 제거, 조연성물질 차단, 발화원 소거가 폭발을 막는 원리입니다.","가연성 혼합가스에 불활성가스를 넣어 산소농도를 최소산소농도 이하로 낮춘다":"산소농도를 최소산소농도 이하로 떨어뜨리려고 가연성 혼합가스에 불활성가스를 주입하는 작업입니다.","가연성 혼합기를 점화시키는 데 필요한 최소 에너지이다":"최소점화에너지는 가연성 혼합기에 불을 붙이는 데 필요한 가장 작은 에너지입니다.","가이드 베인이 있는 것을 터빈펌프라 한다":"원심펌프 가운데 가이드 베인이 달린 것을 터빈펌프라 합니다.","가정용 소용량(100m³/h) 가스미터이다":"막식은 가정용으로 쓰는 100m³/h 규모의 소용량 가스미터입니다.","가합점 치환·직렬 결합은 보기와 달리 하나의 틀에서 정리하지 않는다":"가합점 치환과 직렬 결합은 하나의 틀에서 같이 정리하지 않습니다.","감도는 측정기가 감지하는 최소 변화량이며 정상상태 간 변화 응답은 과도응답이다":"감도는 측정기가 감지할 수 있는 최소 변화량이고, 정상상태 사이의 변화에 대한 응답은 과도응답입니다.","같은 두께에서 고진공단열보다 단열효과가 우수하고 높은 진공도가 필요하다":"다층진공단열은 같은 두께에서 고진공단열보다 단열효과가 좋지만 높은 진공도가 필요합니다.","같은 용량·압력에서 구형보다 두께가 크고 횡형이 수직형보다 안전하다":"원통형 탱크는 구형보다 같은 용량·압력에서 두꺼워지고, 횡형이 수직형보다 안전한 편입니다.","검출부·전달부·수신부로 구성된다":"계측기는 검출부, 전달부, 수신부로 이루어집니다.","경계책 주위에는 무단출입 금지 경계표지를 붙인다":"경계책 둘레에는 무단출입을 금하는 경계표지를 붙입니다.","경계표지와는 별도로 게시하며 가스 명칭은 노란색으로 쓰지 않는다":"독성가스 식별표지는 경계표지와 따로 게시하고 가스 명칭을 노란색으로 쓰지 않습니다.","경시변화가 적어 안정적이나 측정 상한은 열전대보다 낮다":"측온저항체는 시간이 지나도 값이 잘 변하지 않아 안정적이지만 측정 상한은 열전대보다 낮습니다.","계기오차·환경오차·이론오차·개인오차로 분류된다":"계통오차는 계기오차, 환경오차, 이론오차, 개인오차로 나뉩니다.","계량실 1주기 체적 표시는 ℓ/rev 단위이다":"계량실이 한 번 채워졌다 비워지는 한 주기의 체적은 ℓ/rev 단위로 표시합니다.","계측기가 측정량 변화에 민감한 정도이다":"감도는 계측기가 측정량 변화에 얼마나 민감한지를 나타냅니다.","계측기 일반 구성에 들지 않는다":"제어부는 계측기의 일반적인 구성에 들어가지 않습니다.","계통오차와 우연오차로 나뉜다":"정오차는 계통오차와 우연오차로 나뉩니다.","고규소철·흑연봉·자성산화철이고 마그네슘은 희생양극이다":"외부전원법의 양극 재료는 고규소철, 흑연봉, 자성산화철이며 마그네슘은 희생양극에 씁니다.","고무판·가마니를 갖추고 가연성·산소 운반 차량에는 소화설비를 갖춘다":"운반 차량에는 고무판과 가마니를 갖추고, 가연성·산소 운반 차량에는 소화설비도 갖춥니다.","고법 적용 10톤 이상 아르곤 탱크는 내진설계 대상이다":"고법을 적용받는 아르곤 탱크는 10톤 이상일 때 내진설계 대상에 듭니다.","고법 적용 3톤 이상 암모니아 탱크는 대상이 아니다":"고법 적용 암모니아 탱크는 3톤 이상이어도 내진설계 대상이 아닙니다.","고속·고압 유체에 쓰이고 압력손실이 오리피스보다 작다":"플로우 노즐은 고속·고압 유체에 쓰이며 오리피스보다 압력손실이 작습니다.","고압가스 관련 자격증과 용량환산표도 휴대한다":"고압가스 관련 자격증과 용량환산표도 함께 지니고 다닙니다.","고압가스설비는 상용압력의 1.5배 이상으로 내압시험하고 에어졸은 정압충전 레벨장치를 쓴다":"고압가스설비 내압시험은 상용압력의 1.5배 이상으로 하고, 에어졸에는 정압충전 레벨장치를 씁니다.","고압가스 안전장치로 쓰이나 이 분류에서는 제외된다":"가용전식은 고압가스 안전장치로 쓰이지만 이 분류에서는 빠집니다.","고압가스 충전시설의 안전밸브 점검은 1년에 1회 이상이다":"충전시설 안전밸브는 해마다 한 번 이상 점검합니다.","고압건조기와 충전용 교체밸브·충전용지관 사이에도 설치한다":"아세틸렌 쪽에서는 고압건조기와 충전용 교체밸브 사이, 충전용지관에도 역류를 막는 장치를 둡니다.","고압·고점도의 소유량에 적당하고 정량 토출이 가능하다":"소유량이면서 압력과 점도가 높은 액체에 알맞고 정량으로 토출할 수 있습니다.","고압에 견디기 쉽고 만네스만식이 대표적이다":"이음매 없는 용기는 고압에 견디기 쉬우며 만네스만식이 대표적인 제조법입니다.","고온·고압 환경에서 사용이 편리하지 않다":"초음파식은 고온·고압 환경에서 쓰기에는 불편합니다.","고온에서 수증기와 반응해 일산화탄소와 수소를 생성한다":"고온에서 수증기를 만나면 일산화탄소와 수소가 생기는 반응이 메탄에서 일어납니다.","고온에서 수증기와 작용하면 일산화탄소와 수소를 생성한다":"메탄은 고온에서 수증기와 반응하면 일산화탄소와 수소를 만듭니다.","고장 정차 시 적색 표지판을 설치한다":"고장으로 서야 할 때는 적색 표지판을 세워 알립니다.","고정탄소가 많아져 발열량이 커진다":"탄화도가 높아지면 고정탄소가 늘어 발열량이 커집니다.","고정탱크 차량 운행 시 탱크 테이블·차량등록증·고압가스 이동계획서를 휴대한다":"고정탱크 차량이 운행할 때는 탱크 테이블, 차량등록증, 고압가스 이동계획서를 지녀야 합니다.","고진공단열·분말진공단열·다층진공단열이다":"저온장치 단열법에는 고진공단열, 분말진공단열, 다층진공단열이 있습니다.","고체·액체 연료의 발열량을 잰다":"봄베 열량계는 고체나 액체 연료의 발열량을 재는 데 씁니다.","공급압력 자동승압특성은 선정 기준이 아니다":"공급압력이 저절로 올라가는 특성은 정압기를 고르는 기준에 들지 않습니다.","공급자는 수요자가 LPG 특정사용자인지 확인하고 소형저장탱크 잔량을 확인한 뒤 충전한다":"충전 전에 수요자가 LPG 특정사용자인지, 소형저장탱크에 남은 양이 얼마인지 살핍니다.","공기를 넣어 발열량이 큰 가스로 혼합공급하는 것은 기능이 아니다":"공기를 섞어 발열량이 큰 가스를 만들어 내보내는 일은 가스홀더의 기능이 아닙니다.","공기보다 무겁고 완전연소 시 탄산가스와 물이 생긴다":"프로판은 공기보다 무겁고 완전연소하면 이산화탄소와 물이 됩니다.","공기 온도가 낮을수록 길어지는 것은 아니다":"공기 온도가 낮다고 화염이 길어지는 것은 아닙니다.","공기 유속이 높을수록 길어지는 것도 아니다":"공기 유속이 높다고 화염이 길어지는 것도 아닙니다.","공기 조절기를 너무 많이 열거나 염공이 막혀 내압이 높아져도 일어난다":"공기 조절기를 지나치게 열거나 염공이 막혀 내압이 올라가도 리프팅이 생깁니다.","공기 중 메탄이 60%인 기체는 폭발범위 밖이라 폭발하지 않는다":"공기 중 메탄이 60%이면 폭발범위를 벗어나 폭발하지 않습니다.","공기 중 메탄이 60%인 혼합기는 폭발범위 밖이라 폭발하지 않는다":"메탄 농도 60%의 혼합기는 범위를 벗어나 폭발이 일어나지 않습니다.","공기 중에서 연소하고 폭발한계 하한이 10% 이하이다":"공기 중에서 타며 폭발한계 하한이 10% 이하인 가스가 가연성가스입니다.","공기혼합 시 발열량 조절·누설 손실 감소·연소효율 증대 효과가 있다":"공기를 섞어 공급하면 발열량을 조절하고 누설 손실을 줄이며 연소효율을 높입니다.","과방식 염려가 없고 타 매설금속 간섭이 거의 없다":"희생양극법은 과방식 염려가 없고 다른 매설금속에 거의 간섭하지 않는 장점이 있습니다.","과열 탱크의 액화가스가 분출·기화해 착화·폭발하는 현상이다":"BLEVE는 가열된 탱크에서 액화가스가 분출·기화해 불이 붙고 폭발하는 현상입니다.","관 속에 방해물이 있거나 점화에너지가 클수록":"관 속에 방해물이 있거나 점화에너지가 클수록 폭굉유도거리가 짧아집니다.","관의 길이에 비례하며 반비례하지 않는다":"마찰저항은 관의 길이에 비례하며 반비례하지 않습니다.","교체는 용기제조자의 수리범위가 아니다":"냉동기 단열재 교체는 용기제조자가 할 수 있는 수리가 아닙니다.","구동압력이 저하하면 메인밸브가 열린다":"구동압력이 낮아질수록 메인밸브가 열리는 구조가 언로딩형 정압기의 특징입니다.","구리-콘스탄탄·백금-백금로듐·크로멜-알루멜이다":"열전대 재료 조합은 구리와 콘스탄탄, 백금과 백금로듐, 크로멜과 알루멜입니다.","구리가 많아지면 냉간가공성이 나빠진다":"구리 함량이 늘면 냉간가공성이 나빠집니다.","구조가 간단하고 감도가 예민하며 기차 조정이 쉬워야 한다":"가스미터는 구조가 간단하고 감도가 예민하며 기차 조정이 쉬운 것이 좋습니다.","구조가 간단하고 제작비가 싸다":"차압식 유량계는 구조가 간단하고 제작비가 적게 듭니다.","구조가 간단하나 통풍 상태에 따라 오차가 생기고 물이 필요하다":"건습구 습도계는 구조가 간단하지만 통풍 상태에 따라 오차가 생기고 물이 필요합니다.","구조·온도 상승에 대한 안전도를 높인 구조이다":"안전증 방폭은 구조와 온도 상승에 대한 안전도를 더 높인 구조입니다.","국부온도·넓은 범위 측정과 빠른 응답이 가능하고 열용량이 작다":"열전대는 열용량이 작아 국부 온도와 넓은 범위를 빠르게 잴 수 있습니다.","굴뚝을 높게 하는 것은 NOx 저감 방법이 아니다":"굴뚝을 높이는 것으로는 NOx를 줄일 수 없습니다.","그릇은 삼발이보다 폭이 좁은 것을 쓰고 잔가스 사용을 위해 용기를 가열하지 않는다":"삼발이보다 폭이 좁은 그릇을 쓰고, 잔가스를 쓰려고 용기를 가열하지 않습니다.","그 후에는 상용압력의 10%씩 단계적으로 승압한다":"이어서 상용압력의 10%씩 단계적으로 압력을 올려 갑니다.","금속산화물을 환원시키고 고온·고압에서 철을 탈탄시킨다":"수소는 고온에서 금속산화물을 환원하는 성질이 있고, 고온·고압에서는 철에서 탄소를 빼앗습니다.","금속화재이며 가스화재가 아니다":"D급 화재는 금속이 타는 화재이고 가스가 타는 화재는 아닙니다.","기름면 위의 가연성 가스에 인화되지 않도록 한 구조이다":"유입방폭구조는 기름면 위에 있는 가연성 가스에 불이 붙지 않게 만든 구조입니다.","기밀성이 좋은 밸브는 플러그·볼·게이트밸브이다":"기밀성이 좋은 밸브로는 플러그밸브, 볼밸브, 게이트밸브가 있습니다.","기밀시험은 최고충전압력의 1.1배이다":"초저온가스용 용기의 기밀시험 압력은 최고충전압력의 1.1배입니다.","기상 폭발이 아니라 물리적 폭발에 속한다":"증기폭발은 기상 폭발이 아니라 물리적 폭발에 속합니다.","기초 구조가 간단하고 표면적이 작으며 강도가 높다":"구형 탱크는 표면적이 작고 강도가 높으며 기초 구조도 간단합니다.","기화량을 가감할 수 있고 설비장소는 작아진다":"기화량을 조절할 수 있고 설비 장소가 작아도 됩니다.","기화장치 구성은 기화부·제어부·조압부이고 온수 가열방식은 온수 80℃ 이하이다":"기화장치는 기화부, 제어부, 조압부로 구성되고 온수 가열방식은 온수를 80℃ 이하로 씁니다.","기화장치에는 액화가스가 넘쳐흐르는 것을 방지하는 장치를 설치한다":"액화가스가 넘치는 것을 막는 장치를 기화장치에 달아야 합니다.","기화하면 체적이 약 250배로 팽창하고 발열량은 LNG보다 크다":"LPG는 기화하면 체적이 약 250배 늘어나며 발열량이 LNG보다 큽니다.","긴급차단장치는 저장설비 내부에 설치해도 되고 동력원은 액압·기압·전기·스프링이다":"긴급차단장치는 저장설비 안에 둘 수 있으며 액압, 기압, 전기, 스프링을 동력원으로 씁니다.","길이·광도·물질량이며 밀도는 유도단위이다":"길이, 광도, 물질량은 기본단위이고 밀도는 기본단위를 조합한 유도단위입니다.","낮은 압력에서 짧아지는 것이 아니다":"낮은 압력에서 폭굉유도거리가 짧아지는 것은 아닙니다.","내관·연소기·공동주택 외벽 가스계량기가 있다":"사용시설에는 내관, 연소기, 공동주택 외벽에 단 가스계량기가 있습니다.","내부반응 감시장치는 배관 안전제어 장치로 요구되지 않는다":"배관 안전제어 장치 요구 목록에 내부반응 감시장치는 없습니다.","내부응력을 제거하고 연화하며 인성을 높인다":"풀림(소둔)을 하면 내부응력이 없어지고 연화되며 인성이 높아집니다.","내식성과 열변형에 강하고 굴곡성이 좋아 가공이 쉽다":"동관은 내식성이 좋고 열변형에 강하며 잘 휘어서 가공하기 쉽습니다.","내압방폭 가연성가스 화염일주한계는 A등급 0.9mm 이상이다":"내압방폭의 화염일주한계가 0.9mm 이상인 가연성가스는 A등급입니다.","내압시험에 합격한 연월과 동판 두께(t)도 각인한다":"동판 두께(t)와 내압시험에 합격한 연월 역시 용기에 새깁니다.","내열성·내압성이 좋고 계량법상 유효기간을 만족해야 한다":"내열성과 내압성이 좋고 계량법상 유효기간을 지키는 가스미터를 고릅니다.","내통에는 18-8 스테인리스강을 쓴다":"암모니아 합성탑 내통에는 18-8 스테인리스강을 씁니다.","냉동기 냉매설비에서 두께 40mm 이상 탄소강은 초음파탐상 대상이다":"냉동기 냉매설비 탄소강은 두께가 40mm 이상이면 초음파탐상을 받습니다.","냉매가스가 배관으로 공통인 냉동설비는 냉동능력을 합산한다":"냉매가스가 배관으로 이어져 있는 냉동설비는 냉동능력을 합산합니다.","냉매가스 압력이 설계압력 이상이면 즉시 상용압력 이하로 되돌리는 장치가 필요하다":"냉매가스 압력이 설계압력 이상이 되면 곧바로 상용압력 이하로 되돌리는 장치를 갖춰야 합니다.","냉매계통이 달라도 1개 규격품으로 인정되는 설비는 합산 대상이다":"냉매계통이 달라도 규격품 1개로 인정되는 설비는 냉동능력을 합칩니다.","냉매는 안전성이 있고 증발열이 커야 한다":"증발열이 크고 안전성이 있는 물질이 냉매로 알맞습니다.","냉매설비는 설계압력 이상으로 기밀시험·내압시험을 한다":"설계압력보다 높거나 같은 압력으로 냉매설비의 기밀시험과 내압시험을 합니다.","농도가 TLV-TWA 기준농도 이하가 될 때까지 치환한다":"독성가스 설비는 농도가 TLV-TWA 기준농도 이하로 내려갈 때까지 치환합니다.","농도가 높고 난류확산이 있으면 위험이 커지고 수분이 늘면 위험이 줄어든다":"분진 농도가 짙고 난류확산이 있으면 위험하고, 수분이 늘면 위험도가 감소합니다.","높이 1.5m·두께 10cm 철근콘크리트 벽이 아니다":"방호벽을 높이 1.5m, 두께 10cm 철근콘크리트 벽으로 정의하는 것은 틀립니다.","다공도가 80%이면 합격이다":"다공도가 80%이면 이 기준 범위 안에 있어 합격입니다.","다공물질에 침윤시키는 용제는 아세톤·디메틸포름아미드이다":"아세틸렌 용기의 다공물질에 스며들게 하는 용제는 아세톤과 디메틸포름아미드입니다.","다이어프램·회전자·습식이고 와류식은 실측식이 아니다":"실측식 가스미터에는 다이어프램, 회전자, 습식이 있고 와류식은 해당하지 않습니다.","단속적이라 맥동이 일어나기 쉽고 진동과 설치면적이 크다":"토출이 단속적이라 맥동이 생기기 쉽고 진동이 있으며 설치면적이 큽니다.","단위화상 면적에 대한 최대증발량은 연소율이 아니다":"단위화상 면적당 최대증발량은 연소율의 정의가 아닙니다.","단층 저진공단열법은 해당하지 않는다":"단층 저진공단열법이라는 방식은 여기에 해당하지 않습니다.","담금질(소입)은 신율을 줄이고 뜨임(소려)은 취성을 작게 한다":"신율을 낮추는 처리가 담금질(소입)이고, 취성을 줄이는 처리가 뜨임(소려)입니다.","담배연기 등 잡가스에 울리지 않고 연소기 폐가스가 닿는 곳에 설치하지 않는다":"검지경보장치는 담배연기 같은 잡가스에 울리지 않아야 하고 연소기 폐가스가 닿는 곳에는 달지 않습니다.","대기압 분해폭발 물질로 보지 않는다":"시안화수소는 대기압 분해폭발 물질로 보지 않습니다.","대기압에 게이지압을 더한 값이다":"절대압은 대기압에 게이지압을 더한 값입니다.","대량 수요에 적합하고 용량범위가 100~5,000m³/h이다":"루트미터는 대량 수요처에 알맞고 용량 범위가 100~5,000m³/h입니다.","대상 가스용품의 수시품질검사는 1년에 1회 이상이다":"대상 가스용품은 수시품질검사를 1년에 한 번 이상 받습니다.","대상물 접지·공기 이온화·상대습도 상승으로 줄인다":"정전기는 대상물 접지, 공기 이온화, 상대습도 상승으로 줄입니다.","대유량 측정에 적합하고 중압가스 계량이 가능하다":"루트미터는 대유량을 재기에 알맞고 중압가스도 계량할 수 있습니다.","대체(합성) 천연가스를 뜻한다":"SNG는 대체 또는 합성 천연가스를 가리킵니다.","도법 3톤 이상 저장탱크와 액법 3톤 이상 LPG 저장탱크도 대상이다":"도법 저장탱크와 액법 LPG 저장탱크는 3톤 이상이면 대상에 포함됩니다.","도시가스는 천연가스에서 원유까지 넓은 원료를 사용한다":"도시가스 원료는 천연가스부터 원유까지 폭이 넓습니다.","도시가스배관은 최고사용압력 0.5MPa 이상이 내진설계 대상이다":"최고사용압력이 0.5MPa 이상인 도시가스배관이 내진설계를 해야 하는 대상입니다.","도시가스보다 열용량·발열량이 크고 조성이 일정하다":"도시가스와 견주면 열용량과 발열량이 더 크고 성분 조성은 늘 같습니다.","도시가스 사용시설 시험은 상용압력의 50%까지 승압한다":"도시가스 사용시설은 시험할 때 처음에 상용압력의 50%까지만 압력을 올립니다.","도시가스 압력조정기 입구 쪽은 최대입구압력의 1.5배 이상으로 내압시험한다":"입구 쪽 내압시험은 도시가스 압력조정기의 최대입구압력을 1.5배 이상 올려서 합니다.","독성가스가 아니라 제해설비 대상이 아니다":"아세틸렌은 독성가스가 아니어서 제해설비 대상이 아닙니다.","독성가스 용기보관실은 누출가스 확산을 적절히 방지해야 한다":"독성가스 용기보관실은 누출가스가 퍼지는 것을 제대로 막아야 합니다.","독성 압축가스 100m³ 이상, 액화산소 6000kg 이상이 기준이다":"독성 압축가스는 100m³ 이상일 때, 액화산소는 6000kg 이상일 때 운반책임자가 따라갑니다.","동족체는 분자량이 증가할수록 AIT가 감소하며 용기가 작아지면 AIT는 증가한다":"동족체는 분자량이 커질수록 AIT가 낮아지고, 용기가 작아지면 AIT는 높아집니다.","되먹임 폐루프를 하나의 전달요소로 합친다":"피드백 결합은 되먹임이 있는 폐루프를 하나의 전달요소로 합치는 변환입니다.","두께 50mm 이상 탄소강은 초음파탐상시험에 합격해야 한다":"탄소강 두께가 50mm 이상이면 초음파탐상시험을 통과해야 합니다.","두 평행판 사이 화염이 전파하지 않는 한계 거리이다":"소염거리는 두 평행판 사이에서 화염이 더는 전파되지 못하는 한계 간격입니다.","드럼 회전수로 통과유량을 체적으로 구하며 정도가 좋고 설치공간이 크다":"드럼이 몇 번 도는지로 통과한 가스 체적을 알아내는 습식 미터는 정도가 좋은 대신 차지하는 공간이 큽니다.","등심연소 화염의 길이는 공기 온도가 높을수록 길어진다":"등심연소에서는 공기 온도가 높을수록 화염이 길어집니다.","또는 폭발한계 상한과 하한의 차가 20% 이상인 가스이다":"폭발한계 상한과 하한의 차가 20% 이상인 가스도 가연성가스로 봅니다.","뜨거운 액체가 차가운 액체와 접촉해 급속히 증기가 되는 폭발이다":"뜨거운 액체가 차가운 액체와 닿아 순식간에 증기가 되면서 일어나는 폭발이 증기폭발입니다.","린데 고압식·클라우드식·캐피자식이다":"가스액화 사이클에는 린데 고압식, 클라우드식, 캐피자식이 있습니다.","마찰저항은 유체 점도가 크면 커진다":"유체의 점도가 크면 배관 마찰저항도 커집니다.","막식·델타식·회전자식 미터가 있다":"가스 유량을 재는 미터로는 막식, 델타식, 회전자식이 있습니다.","막식·로터리피스톤식은 추량식이 아니다":"막식과 로터리피스톤식은 추량식 가스미터가 아닙니다.","매연·먼지 제거에 건식과 습식을 구분해 쓴다":"매연과 먼지를 거를 때는 건식과 습식을 구분해서 씁니다.","매월 1회나 1주일 1회 점검이 기준이 아니다":"점검 기준 주기를 매월 1회나 1주일 1회로 말하면 틀립니다.","맥동이 적고 윤활유가 불필요하다":"원심압축기는 맥동이 적고 윤활유를 쓰지 않아도 됩니다.","메탄은 고온에서 수증기와 작용해 일산화탄소와 수소를 생성한다":"메탄은 고온에서 수증기와 만나 일산화탄소와 수소로 바뀝니다.","모세관 현상이 작고 혼합성분이면 안 된다":"모세관 현상이 작아야 하고, 여러 성분이 섞인 액체는 쓰면 안 됩니다.","문자는 30m 이상 거리에서 식별할 수 있어야 한다":"식별표지 문자는 30m 이상 떨어진 곳에서도 알아볼 수 있어야 합니다.","물에 녹지 않아야 하며 연소 후에는 냄새가 남지 않아야 한다":"부취제는 물에 녹지 않아야 하고 연소한 뒤에는 냄새가 남지 않아야 합니다.","물에 잘 녹고 증발잠열이 커 냉매로 쓰며 동을 직접 쓸 수 없다":"물에 잘 녹고 증발잠열이 큰 성질 덕에 냉매로 쓰이며, 동 재질은 직접 접촉시킬 수 없습니다.","물·흡수제로 흡수·중화하거나 흡착제로 제거한다":"새어 나온 가스는 물이나 흡수제로 흡수·중화하거나 흡착제로 걷어 냅니다.","미분탄 연소는 2상류 상태이고 낮은 공기비로 높은 연소효율을 얻는다":"미분탄 연소는 고체와 기체가 섞인 2상류 상태이고 낮은 공기비에서도 연소효율이 높습니다.","미터 내압시험은 1,000mmH₂O로 약 3분간 유지한다":"미터 내압시험은 압력 1,000mmH₂O를 약 3분 동안 가해 버티는지 봅니다.","밀도·비중은 유체의 무게나 부력을 이용해 잰다":"유체의 무게나 부력으로 밀도와 비중을 잴 수 있습니다.","밀폐형 연소기는 급·배기통과 벽 사이로 배기가스가 실내에 들어오지 않게 한다":"밀폐형 연소기에서는 급·배기통 둘레 틈새로 배기가스가 실내로 새어 들면 안 됩니다.","바닥으로부터 1.6m 이상 2m 이내이다":"가스미터는 바닥에서 1.6m 이상 2m 이내 높이에 답니다.","반응활성도가 클수록, 분자구조가 복잡할수록 낮아진다":"반응활성도가 크거나 분자구조가 복잡할수록 착화온도가 내려갑니다.","발연황산·브롬 시약은 이들 가스 검사 시약이 아니다":"이들 가스를 검사할 때 발연황산이나 브롬 시약을 쓰지는 않습니다.","발열량이 높을수록 착화온도가 낮아진다":"발열량이 높은 가연물일수록 낮은 온도에서 착화합니다.","발열반응이며 빛이 나고 연소 생성물의 온도가 오른다":"연소는 발열반응이어서 빛이 나고 연소 생성물의 온도가 오릅니다.","발열반응이며 짧은 시간에 에너지가 방출된다":"폭굉에서는 발열반응이 일어나 짧은 시간에 에너지가 방출됩니다.","방류둑은 액밀해야 하고 높이에 상당하는 액두압에 견뎌야 한다":"방류둑은 액이 새지 않아야 하고 높이만큼의 액두압에 견뎌야 합니다.","방사선투과 촬영은 길이이음과 원둘레이음의 교차부도 포함한다":"방사선투과 촬영 범위에는 길이이음과 원둘레이음이 만나는 교차부도 들어갑니다.","방사율 보정이 필요하며 고온 측정이 가능하다":"비접촉식 온도계는 방사율 보정이 필요하며 고온을 잴 수 있습니다.","방전복 등으로 인체 정전기도 방지한다":"방전복 등을 입으면 사람 몸에 쌓이는 정전기도 막을 수 있습니다.","방폭전기기기 설계에 쓰는 값이다":"안전간격은 방폭전기기기를 설계할 때 기준으로 삼는 값입니다.","배관설비는 상용압력의 2배 이상에서 항복을 일으키지 않는 두께로 한다":"상용압력의 2배 이상에서도 항복하지 않을 두께로 배관설비를 만듭니다.","배관에는 압력 안전장치·긴급차단장치·가스누출검지경보장치를 설치한다":"압력 안전장치, 긴급차단장치, 가스누출검지경보장치를 배관에 설치합니다.","배관 외면에서 도로 경계까지 수평거리는 1m 이상이며 2m가 아니다":"도로 경계에서 배관 바깥면까지의 수평거리는 최소 1m이고 2m는 요구되지 않습니다.","배관은 도로 밑 다른 시설물과 0.3m 이상 거리를 둔다":"도로 밑 배관은 다른 시설물과 0.3m 이상 떨어뜨려 묻습니다.","배관은 지면에서 최소 1m 이상 깊이에 매설한다":"독성가스 배관은 지면에서 최소 1m 이상 깊이에 묻습니다.","배관·지반의 상호작용 해석 시 배관의 유연성과 변형성을 고려한다":"배관과 지반이 서로 영향을 주는 상호작용을 해석할 때는 배관의 유연성과 변형성을 따집니다.","배기통 재료는 스테인리스 강판이나 내열·내식성 재료를 쓴다":"배기통은 스테인리스 강판이나 열과 부식에 강한 재료로 만듭니다.","배선이 쉽고 신호 취급이 쉬우나 빠른 비례 조작부를 만들기 어렵다":"전기식은 배선이 쉽고 신호 취급이 쉽지만 빠른 비례 조작부를 만들기는 어렵습니다.","백색이며 밝은 회색이나 황색이 아니다":"액화암모니아 용기는 백색으로 칠하며 밝은 회색이나 황색이 아닙니다.","백필터·사이클론·멀티클론이다":"건식 집진장치에는 백필터, 사이클론, 멀티클론이 있습니다.","버너 내압이 높아져 가스가 과다 유출될 때 일어난다":"리프팅은 버너 내압이 높아져 가스가 지나치게 흘러나올 때 일어납니다.","벤트스택에는 액화가스가 함께 방출되지 않도록 조치하고 기액분리기를 둔다":"액화가스가 섞여 나가지 않도록 벤트스택에 기액분리기를 설치합니다.","벨로우즈식·다이어프램식·부르동관식이다":"탄성식 압력계는 벨로우즈식, 다이어프램식, 부르동관식으로 나뉩니다.","벨로우즈형·루프형(U밴드)·스위블·슬라이드·상온스프링이다":"배관 신축이음에는 벨로우즈형, 루프형(U밴드), 스위블, 슬라이드, 상온스프링이 있습니다.","보호관·열전대선·보상도선이며 저항체 소자는 저항온도계 부품이다":"열전대는 보호관, 열전대선, 보상도선으로 구성되며 저항체 소자는 저항온도계의 부품입니다.","본관·공급관·사용자 공급관이다":"공급시설은 본관, 공급관, 사용자 공급관으로 이루어집니다.","부득이한 경우를 제외하고 장시간 정차하지 않으며 운반책임자와 운전자가 동시에 이탈하지 않는다":"부득이한 경우가 아니면 오래 세워 두지 않고, 운반책임자와 운전자가 함께 자리를 비우지 않습니다.","부식성이 없고 화학적으로 안정해야 한다":"부취제는 부식성이 없고 화학적으로 안정해야 합니다.","부식에 강하고 내한성이 우수하며 상온에서도 유연하다":"가스용 폴리에틸렌관은 부식에 강하고 추위에 잘 견디며 상온에서도 유연합니다.","부자식·압력식·방사선식이 있고 용적식은 아니다":"액면계에는 부자식, 압력식, 방사선식이 있고 용적식은 없습니다.","부취제는 독성이 없어야 한다":"독성이 없는 물질이어야 부취제로 쓸 수 있습니다.","부취제와 메탄은 서로 반응하지 않는다":"부취제와 메탄은 서로 화학반응을 일으키지 않습니다.","부타디엔은 독성가스가 아니고 염소는 가연성이 아니며 아르곤·탄산가스·질소는 불연성이다":"부타디엔은 독성 가스에서 빠지고 염소는 불에 타지 않으며, 아르곤과 탄산가스, 질소는 타지 않는 불연성입니다.","부피조정장치도 봉인 위치로 보지 않는다":"부피조정장치는 봉인하는 위치로 치지 않습니다.","분말·포말·CO₂ 소화기이며 공기를 더 공급하는 것은 소화가 아니다":"분말, 포말, CO₂ 소화기는 질식 소화에 쓰이고, 공기를 더 넣는 것은 소화가 아닙니다.","분무연소는 액체연료 연소방식이다":"분무연소는 액체연료를 태우는 방식입니다.","분자 간 인력과 분자 자신의 부피를 무시한다":"완전가스는 분자 사이의 인력과 분자 자체의 부피를 무시한 가정 위의 기체입니다.","분젠 버너법도 층류연소속도 측정법이다":"분젠 버너법도 층류연소속도를 재는 방법입니다.","분진은 공기 중에 부유할 때 가연성이 되고 점화원이 필요하다":"분진은 공기 중에 떠 있을 때 가연성이 되고, 폭발하려면 점화원이 있어야 합니다.","불꽃은 온도가 오를수록 암적색, 적색, 황적색, 백적색, 휘백색 순으로 변한다":"온도가 오를수록 불꽃 색은 암적색에서 적색, 황적색, 백적색, 휘백색 순으로 바뀝니다.","불순분자의 접근 방지나 쉽게 방류시키기 위한 것이 아니다":"불순분자의 접근을 막거나 쉽게 방류시키려는 목적이 아닙니다.","불활성 가스로 표면을 덮으면 질식 효과이다":"불활성 가스로 표면을 덮으면 공기가 차단되는 질식 효과가 납니다.","브리지 공급 전류 점검을 확실히 해야 한다":"브리지에 공급하는 전류가 제대로 흐르는지 철저히 살펴야 합니다.","비드 형상이 일정하고 슬러그·스패터가 없어야 하며 보강 덧붙임은 3mm 이상이 아니다":"비드 모양이 고르고 슬러그·스패터가 없어야 하며, 보강 덧붙임 3mm 이상이라는 기준은 없습니다.","비접촉으로 부식성 액체도 재며 측정범위가 넓다":"초음파 레벨계는 액체에 닿지 않고 재서 부식성 액체도 측정하며 측정범위가 넓습니다.","빈 용기는 표시해 충전용기와 구별하며 산소 보관장소에 흡수 재해제는 필요 없다":"빈 용기는 표시를 해서 충전용기와 구별하고, 산소 보관장소에는 흡수 재해제를 두지 않아도 됩니다.","빙점 이하의 낮은 온도 배관에 쓴다":"SPLT는 빙점 이하의 낮은 온도 배관에 씁니다.","사고내용과 피해현황도 통보한다":"사고 내용과 피해 현황까지 함께 알립니다.","사고원인과 피해자 보상 방안은 통보 내용이 아니다":"통보 내용에 사고원인과 피해자 보상 방안은 넣지 않습니다.","사람을 수용하지 않는 독립 단일건물은 보호시설이 아니다":"사람이 들어가 살지 않는 독립 단일건물은 보호시설에 해당하지 않습니다.","사방밸브로 이송방향을 바꿀 수 있고 베이퍼록이 생기지 않는다":"사방밸브를 쓰면 이송방향을 바꿀 수 있고 베이퍼록 걱정이 없습니다.","사용시설 설비는 작동상황을 연 1회 이상 점검한다":"사용시설 설비의 안전밸브는 작동상황을 해마다 한 번 이상 점검합니다.","사이클론 스크러버는 습식 집진장치이다":"사이클론 스크러버는 물을 쓰는 습식 집진장치입니다.","사질토 등 특수성 지반(해저 제외)에서도 확산방지 조치를 한다":"해저를 제외한 사질토 등 특수성 지반에서도 누출가스 확산방지 조치가 필요합니다.","산소농도가 높으면 연소가 늦어지거나 발화온도가 높아지지 않는다":"산소농도가 높다고 연소가 느려지거나 발화온도가 올라가지는 않습니다.","산소는 기밀시험에 쓸 수 없다":"기밀시험용 가스로 산소를 쓸 수는 없습니다.","산소량이 늘수록 AIT는 감소한다":"산소량이 늘수록 자연발화온도(AIT)는 내려갑니다.","산소 없이 자기분해하는 가스는 아세틸렌·산화에틸렌·히드라진이다":"산소 없이도 스스로 분해하는 가스에는 아세틸렌, 산화에틸렌, 히드라진이 있습니다.","산소용기는 화기 취급 장소와 사람 출입이 많은 장소에 저장하지 않는다":"산소용기는 화기를 쓰는 곳과 사람 출입이 많은 곳에 저장하지 않습니다.","산소 저장설비 주위 화기 금지 거리는 8m이며 20m가 아니다":"산소 저장설비에서 화기를 멀리해야 하는 거리는 8m이지 20m가 아닙니다.","산소 중 가연성가스 용량이 4% 이상이면 압축하지 않으며 3%가 아니다":"산소 중에 가연성가스가 용량으로 4% 이상 들어 있으면 압축하지 않으며 3%라는 값은 틀립니다.","산이나 할로겐과 잘 화합한다":"암모니아는 산이나 할로겐과 잘 결합합니다.","산화철에 CaO를 첨가한 것을 쓴다":"촉매로는 산화철에 CaO를 첨가한 것을 씁니다.","산화철에 K₂O 및 Al₂O₃를 첨가한 것도 촉매로 쓴다":"산화철에 K₂O와 Al₂O₃를 첨가한 것도 암모니아 합성 촉매로 씁니다.","상온 건조 상태의 염소에는 보통강(탄소강)을 쓸 수 있다":"건조하고 상온인 염소를 다룰 때는 탄소강인 보통강을 쓸 수 있습니다.","상용압력의 1.5배 이상 2배 이하의 최고 눈금이 있어야 한다":"압력계는 상용압력의 1.5배 이상 2배 이하 최고 눈금을 가진 것을 씁니다.","상용압력의 8/10이나 1.5배 이하가 아니다":"작동압력을 상용압력의 8/10이나 1.5배 이하로 잡는 것은 기준이 아닙니다.","상용온도에서 0.2MPa 이상인 액화가스도 고압가스이다":"액화가스는 상용온도 압력이 0.2MPa 이상이면 고압가스에 해당합니다.","상용온도에서 압력 1MPa 이상인 압축가스가 고압가스이다":"압축가스는 상용온도 압력이 1MPa 이상이면 고압가스에 해당합니다.","상한치와 하한치를 가지며 연소에 필요한 혼합가스의 농도이다":"연소범위는 연소가 가능한 혼합가스 농도의 하한치와 상한치 사이 구간입니다.","생가스·변성가스·공기혼합가스 공급방식이다":"LP가스 공급방식에는 생가스, 변성가스, 공기혼합가스 공급이 있습니다.","생산공정검사 대상의 공정확인심사는 6개월에 1회가 아니다":"생산공정검사 대상의 공정확인심사 주기가 6개월에 1회라는 설명은 틀립니다.","생산공정검사 대상의 정기품질검사는 1개월에 1회가 아니다":"생산공정검사 대상의 정기품질검사를 1개월에 1회 한다는 설명은 틀립니다.","서로 다른 두 금속이 접촉해 일어나는 부식이다":"갈바닉 부식은 서로 다른 두 금속이 접촉해서 일어나는 부식입니다.","서징·수격작용·캐비테이션이다":"펌프의 이상현상에는 서징, 수격작용, 캐비테이션이 있습니다.","석유류·글리세린은 산소압축기 내부 윤활제로 쓰지 않는다":"산소압축기 안쪽에는 석유류나 글리세린 윤활제를 쓸 수 없습니다.","석유정제 100톤 이상·석유화학·철강 1만m³ 이상이며 비료는 아니다":"특정제조 대상에는 1만m³ 이상 철강, 석유화학, 100톤 이상 석유정제가 있고 비료는 없습니다.","설정압 이상이 되면 서서히 열리며 작동 후 전체 교환이 필요하지 않다":"스프링 안전밸브는 설정압을 넘으면 서서히 열리며 작동한 뒤 전체를 바꿀 필요는 없습니다.","설치 면적이 작으나 스트레이너 설치가 필요하다":"루트미터는 설치 면적이 작지만 스트레이너를 달아야 합니다.","설치면적이 크고 원심형이 아니며 저압용으로 한정되지 않는다":"왕복식은 설치면적이 큰 편이고 원심형이 아니며, 저압용에만 쓰는 것도 아닙니다.","성토는 수평에 대해 45° 이하의 기울기로 하며 30° 이하가 아니다":"성토 기울기는 수평에 대해 45° 이하이고, 30° 이하라는 설명은 맞지 않습니다.","성토 윗부분의 폭은 30cm 이상이다":"성토 방류둑의 윗부분은 폭이 30cm 이상이어야 합니다.","소석회·가성소다를 살포하고 중화제 후 폴리에틸렌 시트로 덮는다":"액체염소가 누출되면 소석회나 가성소다를 뿌리고, 중화제를 쓴 뒤 폴리에틸렌 시트로 덮습니다.","소요동력과 압축 일량이 증가한다":"압축비가 커지면 소요동력과 압축 일량이 늘어납니다.","수분을 함유한 메탄이 금속을 급격히 부식시키지는 않는다":"수분이 든 메탄이 금속을 급격히 부식시키지는 않습니다.","수분이 많으면 통풍불량, 회분이 많으면 열효율이 저하된다":"수분이 많으면 통풍이 나빠지고 회분이 많으면 열효율이 떨어집니다.","수소가 가장 넓고 프로판이 가장 좁다":"폭발범위가 가장 넓은 가스는 수소이고 가장 좁은 가스는 프로판입니다.","수소가스가 섞이면 지시값을 높여 주는 것이 아니라 오차를 준다":"수소가 섞이면 지시값을 높여 주기보다 오차를 일으킵니다.","수소는 불완전연소해도 CO가 생기지 않고 CO₂·NH₃ 등은 가연성 가스가 아니다":"수소가 덜 타더라도 CO는 만들어지지 않으며, CO₂와 NH₃ 같은 가스는 가연성이 아닙니다.","수소도 임계온도가 낮아 상온에서 액화가 불가능하다":"수소도 임계온도가 낮아 상온에서는 액화할 수 없습니다.","수소의 연소범위는 약 4~75%이다":"수소는 공기 중에서 약 4~75% 범위에서 연소합니다.","수요량 변동과 거리에 무관하게 압력이 일정하지는 않다":"저압공급이라고 해서 수요량 변동이나 거리에 상관없이 압력이 일정한 것은 아닙니다.","수요 변화에 맞춰 가스 공급·저장을 조절한다":"가스홀더는 수요가 변하는 만큼 가스 공급과 저장량을 맞춰 줍니다.","수용능력 300명 이상 교회·공연장이다":"수용능력이 300명 이상인 교회와 공연장이 첫째 등급인 보호시설입니다.","수평 2축과 수직 방향 성분을 고려한다":"배관 내진설계는 수평 2축 방향과 수직 방향 성분을 함께 고려합니다.","수평으로 부착하고 입구배관에 드레인을 단다":"가스미터는 수평으로 달고 입구배관에는 드레인을 설치합니다.","순도 98% 이상이어야 하며 99%가 기준이 아니고 저장은 60일을 넘기지 않는다":"순도 기준은 98% 이상이어서 99%라고 하면 틀리고, 저장은 60일을 넘기지 않습니다.","스커트 재료는 KS D 3533 SG295 이상이며 넥크링 탄소함유량은 0.48% 이하가 아니다":"넥크링 탄소함유량 0.48% 이하는 기준이 아니고, 스커트는 KS D 3533 SG295 이상 재료를 씁니다.","스프링 저울·부르동관 압력계·전류계는 편위법이다":"스프링 저울, 부르동관 압력계, 전류계는 지침의 움직임을 읽는 편위법 계기입니다.","슬롯 버너법·비누거품법·평면화염 버너법으로 잰다":"층류연소속도는 슬롯 버너법, 비누거품법, 평면화염 버너법으로 잽니다.","습도가 높은 것을 피하고 열이 쌓이지 않게 퇴적·보관 방법에 주의한다":"습도가 높은 곳을 피하고 열이 쌓이지 않도록 쌓는 방법과 보관 방법을 신경 씁니다.","습증기 열량 측정용이 아니다":"봄베 열량계는 습증기 열량을 재는 기구가 아닙니다.","습증기의 열량 측정에는 조리개·분리·과열 열량계를 쓴다":"습증기의 열량을 잴 때는 조리개 열량계, 분리 열량계, 과열 열량계를 씁니다.","시가지·하천·터널·수로 중 배관 설치 시 누출가스 확산방지 조치를 한다":"시가지, 하천, 터널, 수로 중에 배관을 설치할 때는 누출가스 확산방지 조치를 합니다.","시공이 쉽고 내면이 매끈해 마찰손실이 적다":"내면이 매끈해 마찰손실이 적고 시공도 쉽습니다.","시안화수소 충전 용기는 24시간 정치한다":"시안화수소를 채운 용기는 24시간 정치합니다.","시트는 0.6MPa 이상 공기로 1분 이상 가압해 누출이 없어야 한다":"시트는 0.6MPa 이상 공기로 1분 이상 가압했을 때 새지 않아야 합니다.","식별표지 문자는 가로·세로 10cm 이상이다":"식별표지 문자의 가로와 세로는 각각 10cm 이상이어야 합니다.","신규검사는 외관·다공도·기밀시험이다":"아세틸렌용기 신규검사는 외관, 다공도, 기밀시험으로 이루어집니다.","신규종사 시 특별교육을 1회 받는다":"LPG 배달원은 신규로 종사할 때 특별교육을 1회 받습니다.","실리카겔·분자체(몰레큘러시브)·활성알루미나이다":"컬럼 충전제로는 실리카겔, 분자체(몰레큘러시브), 활성알루미나를 씁니다.","실제공기량에서 이론공기량을 뺀 값이다":"과잉공기량은 실제공기량에서 이론공기량을 뺀 만큼입니다.","실제공기량을 이론공기량으로 나눈 값이다":"공기비는 실제공기량을 이론공기량으로 나누어 구합니다.","아레니우스 법칙으로 표시하며 온도와 관계가 있다":"반응속도상수는 아레니우스 법칙으로 나타내며 온도와 관계가 있습니다.","아세트알데히드·일산화탄소·산화에틸렌은 가연성 가스이다":"가연성 가스로 분류되는 것은 아세트알데히드, 일산화탄소, 산화에틸렌입니다.","아세틸렌·에틸렌·수소 중 산소 용량이 전체의 2% 이상이면 압축하지 않는다":"아세틸렌, 에틸렌, 수소에 산소가 용량으로 전체의 2% 이상 섞여 있으면 압축하지 않습니다.","아세틸렌 용기 다공도는 75% 이상 92% 미만이다":"다공도는 75% 이상이고 92% 미만이어야 아세틸렌 용기로 인정됩니다.","아세틸렌 용기 부속품은 AG이다":"아세틸렌 용기 부속품은 AG로 표시합니다.","아세틸렌을 압축할 때 희석제로 질소·메탄·일산화탄소·에틸렌을 쓴다":"아세틸렌을 압축할 때 질소, 메탄, 일산화탄소, 에틸렌을 희석제로 넣어 줍니다.","아세틸렌 충전용지관과 고압건조기·충전용교체밸브 사이에도 설치한다":"고압건조기와 충전용교체밸브 사이, 그리고 아세틸렌 충전용지관에도 달아야 합니다.","안전간격이 작을수록 위험하며 클수록 위험한 것이 아니다":"안전간격이 작을수록 위험하고, 클수록 위험하다는 설명은 틀립니다.","안전관리책임자는 신규종사 후 6개월 이내 교육을 받는다":"신규종사 6개월 이내에 안전관리책임자는 교육을 받아야 합니다.","안전밸브·누설경보·긴급차단은 방지 장치이고 방호벽은 방호 수단이다":"안전밸브, 누설경보, 긴급차단은 방지 장치이고 방호벽은 피해를 줄이는 방호 수단입니다.","안전밸브는 내압시험압력을 기준으로 정한다":"안전밸브 작동압력은 상용압력이 아니라 내압시험압력을 기준으로 정합니다.","안전밸브 방출구는 지면에서 2m 이상이 아니라 5m 이상 높이에 둔다":"방출구 높이는 지면에서 5m 이상이며, 2m 이상으로 잡는 것은 아닙니다.","안전밸브 방출구는 지상 5m 이상 높이이고 탱크실과 처리설비실은 각각 구분한다":"안전밸브 방출구 높이는 지상 5m 이상이고, 탱크실과 처리설비실은 칸을 나눕니다.","안전밸브 작동과 불활성가스 치환 상황은 해당 점검 항목이 아니다":"이 점검에는 안전밸브 작동과 불활성가스 치환 상황이 항목으로 들어 있지 않습니다.","안전밸브 작동압력은 내압시험압력의 8/10 이하이다":"가연성가스 충전 설비의 안전밸브는 내압시험압력의 8/10 이하에서 작동합니다.","안전성향상계획서·가스안전 영향평가서는 휴대 서류가 아니다":"안전성향상계획서와 가스안전 영향평가서는 운행 때 지니는 서류가 아닙니다.","안전증 방폭은 e, 내압은 d, 압력은 p, 유입은 o이다":"방폭 기호는 안전증이 e, 내압이 d, 압력이 p, 유입이 o입니다.","안층·보강층·바깥층으로 되어 있고 3MPa 이상으로 내압시험한다":"고압고무호스는 안층, 보강층, 바깥층으로 이루어지고 3MPa 이상으로 내압시험을 합니다.","암모니아·아세틸렌 배관에는 구리를 쓰면 안 되고 산소 배관에는 구리합금을 쓸 수 있다":"암모니아와 아세틸렌 배관에서는 구리가 금지이고, 산소 배관만 구리합금을 쓸 수 있습니다.","압력·산소농도가 높을수록 감소하고 질소농도가 증가하면 커진다":"압력과 산소농도가 높을수록 최소점화에너지는 줄고, 질소농도가 늘면 커집니다.","압력손실이 크고 고속·고형물 유체에는 적합하지 않다":"오리피스는 압력손실이 크고 고속이거나 고형물이 섞인 유체에는 알맞지 않습니다.","압력이나 생성물 농도 증가가 항상 반응속도를 높이는 것은 아니다":"압력이나 생성물 농도가 늘어난다고 반응속도가 늘 높아지는 것은 아닙니다.","압력이 높아지면 발화온도는 낮아진다":"압력이 올라가면 발화온도는 내려갑니다.","압력이 높아지면 일반적으로 폭발범위가 넓어진다":"압력이 올라가면 대체로 폭발범위가 넓어집니다.","압력이 높을수록 낮아지며 압력이 작을수록 낮아지는 것은 아니다":"압력이 높으면 착화온도가 낮아지고, 압력이 낮아서 낮아지는 것은 아닙니다.","압력이 오를수록 AIT는 감소한다":"압력이 오를수록 AIT는 내려갑니다.","압력조정기 A/S 기간은 점검 항목이 아니다":"압력조정기의 A/S 기간은 점검 항목에 들지 않습니다.","압력조정기는 50A 이하, 300Nm³/h 이하이다":"도시가스용 압력조정기는 50A 이하, 300Nm³/h 이하 규모를 말합니다.","압력조정 장치 고장·두께 축소·과열이 원인이다":"압력조정 장치 고장, 두께 축소, 과열이 용기가 물리적으로 폭발하는 원인입니다.","압축가스는 PG이며 HG는 압축가스 기호가 아니다":"HG는 압축가스 기호로 쓰지 않으며, 압축가스 부속품은 PG로 표시합니다.","압축기 동력설비를 공통으로 하는 설비도 합산하며 4원 이상 방식은 해당 항목이 아니다":"압축기 동력설비를 같이 쓰는 설비도 합산하고, 4원 이상 방식은 이 항목에 해당하지 않습니다.","압축기와 오토크레이브 사이에 설치한다":"역화방지장치는 압축기와 오토크레이브 사이에 둡니다.","압축기와 저장탱크 사이는 해당하지 않으며 구조는 소염소자·역류방지·방출장치이다":"압축기와 저장탱크 사이는 설치 대상이 아니고, 구조는 소염소자, 역류방지, 방출장치입니다.","압축기와 충전용 주관 사이는 역류방지밸브를 설치한다":"압축기와 충전용 주관 사이에는 역류방지밸브를 달아야 합니다.","압축기와 충전용 주관 사이에는 역류방지밸브를 설치한다":"압축기와 충전용 주관 사이에는 역류방지밸브가 있어야 합니다.","압축기·응축기·팽창밸브·증발기로 구성된다":"증기 압축식 냉동기는 압축기, 응축기, 팽창밸브, 증발기로 이루어집니다.","압축하면 맥동이 생기기 쉽다":"왕복식 압축기는 압축 과정에서 맥동이 생기기 쉽습니다.","압축효율과 흡입효율이 좋아지고 동력이 줄며 밸브 스프링 수명이 늘어난다":"실린더를 냉각하면 압축효율과 흡입효율이 좋아져 동력은 줄고 밸브 스프링은 오래 씁니다.","액상 가스가 누출됐을 때 그 유출을 방지하기 위한 것이다":"방류둑은 액상 가스가 누출됐을 때 유출을 막으려는 시설입니다.","액체공기 중 오존, 공기취입구의 아세틸렌, 윤활유 분해 탄화수소이다":"공기액화장치의 폭발 위험은 액체공기 속 오존, 공기취입구의 아세틸렌, 윤활유가 분해된 탄화수소에서 옵니다.","액체비중은 물보다 가볍고 기체는 공기보다 무겁다":"LPG는 액체일 때 물보다 가볍고 기체일 때 공기보다 무겁습니다.","액체·아세틸렌·바이오가스·침전가스 계량에는 다소 부적합하다":"액체, 아세틸렌, 바이오가스, 침전가스 계량에는 루트미터가 다소 알맞지 않습니다.","액체연료의 인화점 측정법은 타그법·펜스키 마르텐스법·에벨펜스키법이다":"액체연료 인화점은 타그법, 펜스키 마르텐스법, 에벨펜스키법으로 측정합니다.","액화가스는 LPW·LP가 아니라 LG이다":"액화가스 용기 부속품은 LPW나 LP가 아니라 LG로 표시합니다.","액화가스 저장능력이 300kg 이상인 고압가스설비에는 안전밸브를 설치한다":"저장능력이 300kg 이상인 액화가스 고압설비에는 안전밸브가 있어야 합니다.","액화산소 5ℓ 중 탄화수소 탄소 600mg은 운전을 중지할 사유이다":"액화산소 5ℓ 중 탄화수소 탄소가 600mg에 이르면 운전을 멈춰야 합니다.","양극이 소모되므로 보충이 필요하다":"희생양극법의 양극은 시간이 지나며 소모되므로 보충해야 합니다.","얼음이 되어 배관과 밸브를 막아 흐름을 방해한다":"수분은 얼음이 되어 배관과 밸브를 막고 흐름을 방해합니다.","에테르·양초는 증발연소이고 아세틸렌은 확산연소이며 경유는 예혼합연소가 아니다":"증발연소하는 것은 에테르와 양초, 확산연소하는 것은 아세틸렌이며, 경유는 예혼합연소에 해당하지 않습니다.","역화 위험이 없고 가스량 조절범위가 크며 고온 예열이 가능하다":"불꽃이 되돌아갈 위험이 없는 것이 확산연소의 장점이고, 가스량 조절범위가 크며 고온으로 미리 데울 수도 있습니다.","역화의 우려가 있으며 공기를 모두 1차 공기로 취하는 것은 전1차 공기식이다":"분젠식은 역화 우려가 있고, 공기를 모두 1차 공기로 쓰는 방식은 전1차 공기식입니다.","연결 배관에 응축액이 고이지 않게 하며 높이는 착지농도가 폭발하한계 미만이 되도록 한다":"응축액이 연결 배관에 고이지 않도록 하고, 착지농도가 폭발하한계 아래가 되는 높이로 세웁니다.","연료는 인화점 이상으로 예열해 공급하며 인화점 이하로 냉각하지 않는다":"인화점 이하로 식히지 않고 인화점 이상으로 예열해서 연료를 공급합니다.","연소범위가 좁을수록 위험한 것이 아니라 넓을수록 위험하다":"연소범위가 넓을수록 위험하고, 좁을수록 위험한 것은 아닙니다.","연소성 가스가 많이 발생하고 열전도율이 낮을수록 연소가 잘 된다":"열전도율이 낮고 연소성 가스가 많이 나올수록 연소가 쉽게 일어납니다.","연소속도가 빨라지고 발화온도는 낮아진다":"산소농도가 높으면 연소속도가 빨라지고 발화온도는 내려갑니다.","연소속도가 크고 폭발범위가 넓을수록 위험하다":"연소속도가 빠르고 폭발범위가 넓은 가스일수록 위험합니다.","연소실 온도를 높게 유지하고 연소에 충분한 시간을 준다":"완전연소하려면 연소실 온도를 높게 유지하고 충분한 시간을 줘야 합니다.","연소열·고체흡수제·용액흡수제를 이용한다":"화학적 분석은 연소열이나 고체흡수제, 용액흡수제를 이용합니다.","연소온도를 낮게 하면 NOx가 줄어든다":"NOx는 연소온도를 낮추면 감소합니다.","연소 조절이 정확하나 연소속도가 커서 안전한 것은 아니다":"가스연료는 연소 조절이 정확하지만 연소속도가 크다고 해서 안전한 것은 아닙니다.","열과 일이 본질적으로 같다는 것은 제1법칙이다":"열과 일이 본질적으로 같다는 성질을 설명하는 법칙이 제1법칙입니다.","열림방향이 시계바늘 반대방향이어야 한다":"핸들휠은 시계바늘 반대방향으로 돌릴 때 열려야 합니다.","열안정성·항유화성이 크고 화학반응성이 작아야 한다":"압축기 내부 윤활유는 열안정성과 항유화성이 크고 화학반응성이 작아야 합니다.","열은 스스로 저온체에서 고온체로 이동할 수 없다":"열이 스스로 차가운 물체에서 뜨거운 물체로 옮겨 갈 수 없다는 법칙입니다.","열전도율법·적외선흡수법·가스크로마토그래피법이다":"열전도율법, 적외선흡수법, 가스크로마토그래피법이 물리적 가스분석법입니다.","열전도율이 크며 알칼리에는 강하나 산성에는 약하다":"구리관은 열전도율이 크고 알칼리에는 강하지만 산성에는 약합니다.","염분·부식성 약품 부근 등 용기 부식 요인이 있는 장소에 저장하지 않는다":"염분이나 부식성 약품 가까이처럼 용기가 부식될 요인이 있는 곳에는 저장하지 않습니다.","염소가스 압축기에는 진한 황산, LPG 압축기에는 식물성 기름을 쓴다":"염소 압축기 윤활유로는 진한 황산을, LPG 압축기 윤활유로는 식물성 기름을 씁니다.","염소는 독성이 강하고 재해제로 소석회를 쓰며 압축기 윤활유는 진한 황산이다":"염소는 독성이 강해 소석회로 재해를 막고, 압축기 윤활유로 진한 황산을 씁니다.","염소와 산소·수소의 혼합 적재를 금하며 독성가스 탱크 내용적은 1만2천L 이내이다":"염소와 산소·수소를 함께 적재하는 것은 금지이고 독성가스 탱크 내용적은 1만2천L 이내입니다.","염소와 아세틸렌은 동일 차량에 적재하지 않는다":"염소와 아세틸렌은 한 차량에 함께 싣지 않습니다.","염소와 혼합하여 일광을 쬐면 폭발적으로 반응한다":"수소와 염소를 섞어 햇빛을 쬐면 폭발적으로 반응합니다.","염의 길이가 짧고 염의 온도는 약 1300℃이다":"분젠식은 불꽃 길이가 짧고 불꽃 온도가 약 1300℃입니다.","염화비닐관보다 가볍고 일광·열에는 약하다":"폴리에틸렌관은 염화비닐관보다 가볍지만 햇빛과 열에는 약합니다.","염화수소와 질소는 특정고압가스가 아니다":"염화수소와 질소는 특정고압가스에 들지 않습니다.","염화제일동착염지에서 적색으로 변한다":"아세틸렌은 염화제일동착염지를 적색으로 변하게 합니다.","예방·국한·소화·피난 대책이 있다":"방폭대책에는 예방, 국한, 소화, 피난 대책이 있습니다.","오르자트법은 흡수식 화학적 분석법이다":"오르자트법은 가스를 흡수액에 흡수시켜 재는 화학적 분석법입니다.","오리피스 같은 장애물을 두지 않는다":"오리피스 같은 장애물을 배관에 두지 않아야 합니다.","오벌형·왕복피스톤형·로터리형·루트식이다":"용적식 유량계에는 오벌형, 왕복피스톤형, 로터리형, 루트식이 있습니다.","오스테나이트계 스테인리스강으로 제조한다":"초저온 용기는 오스테나이트계 스테인리스강으로 만듭니다.","오프셋을 줄이고 과행량을 적게 한다":"비례동작은 오프셋을 줄이고 과행량을 적게 만듭니다.","온도가 높아지면 연소범위는 넓어지고 난류가 되면 예혼합 화염전파속도가 가속된다":"온도가 높아지면 연소범위가 넓어지고, 난류가 되면 예혼합 화염이 더 빠르게 퍼집니다.","온도가 높아지면 폭발범위는 넓어지고 좁아지지 않는다":"온도가 올라가면 폭발범위는 넓어지며 좁아지는 일은 없습니다.","온도가 높을수록 반응속도가 증가한다":"온도가 높을수록 반응속도가 빨라집니다.","온도 변화에 의한 열응력을 흡수하기 위해 쓴다":"신축이음은 온도 변화로 생기는 열응력을 흡수하려고 씁니다.","온도·산소분압이 높으면 연소속도가 빨라진다":"미연소 혼합기의 온도와 산소분압이 높을수록 연소속도가 빨라집니다.","온도·압력·가스 조성의 영향을 받고 가스 부피는 영향 인자가 아니다":"연소속도는 온도, 압력, 가스 조성에 영향을 받고 가스 부피는 영향 인자가 아닙니다.","온도·압력·가연성 가스 농도의 영향을 받는다":"발화지연시간은 온도, 압력, 가연성 가스 농도의 영향을 받습니다.","온도 제어·조성 억제·착화원 차단으로 한다":"폭발방지는 온도 제어, 조성 억제, 착화원 차단으로 합니다.","완전가스는 보일-샤를 법칙을 만족하고 저온·고압에서는 성립하지 않는다":"완전가스는 보일-샤를 법칙을 따르지만 저온·고압에서는 이 법칙이 성립하지 않습니다.","완전기체에서 정압비열과 정적비열의 차는 Cp－Cv＝R이다":"완전기체에서 정압비열과 정적비열의 차이는 기체상수 R과 같습니다.","완전연소에는 산소 5몰이 필요하다":"프로판을 완전히 태우는 데 산소 5몰이 소요됩니다.","완전연소하면 탄산가스와 물이 생성된다":"부탄이 완전연소하면 이산화탄소와 물이 만들어집니다.","완전연소 후 유해가스가 없고 응축되지 않으며 수용성이 아니어야 한다":"부취제는 완전연소 후 유해가스를 남기지 않고 응축되지 않으며 물에 녹지 않아야 합니다.","완전히 열렸을 때 핸들 방향과 유로 방향이 평행이어야 한다":"볼밸브가 완전히 열렸을 때 핸들 방향과 유로 방향이 나란해야 합니다.","왕복·회전·나사 압축기이고 원심은 아니다":"용적형 압축기는 왕복, 회전, 나사 압축기이고 원심압축기는 용적형이 아닙니다.","외관·인장·압궤시험이고 충격시험은 아니다":"알루미늄 합금 용기의 신규검사는 외관, 인장, 압궤시험이고 충격시험은 아닙니다.","외면 언더컷은 단면이 V자형이 되지 않아야 한다":"외면 언더컷의 단면은 V자 모양이면 안 됩니다.","외부에서 보기 쉬운 곳에 게시한다":"사업소 경계표지는 밖에서 눈에 잘 띄는 곳에 게시합니다.","외부전원법 정류기 출력과 배류법 배류기 출력은 3개월에 1회 이상 점검한다":"외부전원법의 정류기, 배류법의 배류기 출력은 3개월에 한 번 이상 점검합니다.","용기 교환주기의 폭을 넓힐 수 있고 필요한 용기 수는 줄어든다":"자동절체식은 용기 교환주기를 넓힐 수 있어 필요한 용기 수가 줄어듭니다.","용기 내부의 폭발에 견디고 외부로 화염이 전파되지 않는 구조이다":"내압방폭은 용기 내부에서 폭발이 나도 견디고 화염이 밖으로 번지지 않는 구조입니다.","용기 몸체 용접·다공물질 교체·부속품 부품 교체를 할 수 있다":"용기제조자는 용기 몸체 용접, 다공물질 교체, 부속품 부품 교체를 수리할 수 있습니다.","용기 몸통부 재료는 고압가스 용기용 강판 및 강대이다":"용기 몸통부는 고압가스 용기용 강판과 강대로 만듭니다.","용기밸브 이탈·안전밸브 작동·압력계 파열은 가스 분출 원인이다":"가스가 분출되는 원인에는 용기밸브 이탈, 안전밸브 작동, 압력계 파열이 있습니다.","용기 손상·합격표시 훼손·정해진 기간의 경과 때 받는다":"용기를 재검사하는 사유는 용기 손상, 합격표시 훼손, 정해진 기간의 경과입니다.","용기 신규검사에는 진동·부분가열·역화시험이 있고 파괴시험은 아니다":"용기 신규검사는 진동, 부분가열, 역화시험으로 하고 파괴시험은 해당하지 않습니다.","용기에는 내용적(V)과 내압시험압력(TP)을 각인한다":"용기 표면에는 내용적(V)과 내압시험압력(TP)이 새겨져 있어야 합니다.","용기에 충전된 LPG를 판매하는 것이다":"액화석유가스판매사업은 용기에 담긴 LPG를 파는 사업입니다.","용기의 도색·표시 여부와 용기 캡·프로텍터 부착 여부를 확인한다":"용기의 도색·표시 상태와 용기 캡, 프로텍터를 붙였는지 봅니다.","용기의 충전구 나사는 대개 왼나사이다":"가연성 가스 용기의 충전구 나사는 대개 왼나사입니다.","용기 파열은 가열·일광 직사·내용물의 중합반응이 원인이다":"가열, 일광 직사, 내용물의 중합반응이 용기를 파열시키는 원인입니다.","용량 조정범위가 좁고 압축비가 크지 않다":"원심압축기는 압축비가 크지 않고 용량을 조정할 수 있는 범위도 좁습니다.","용접부에는 균열·아크 스트라이크·지그 흔적이 없어야 한다":"균열, 아크 스트라이크, 지그 흔적은 용접부에 있으면 안 되는 결함입니다.","우연오차와 과오오차는 계통오차가 아니며 계통오차는 원인을 알아 제거할 수 있다":"우연오차와 과오오차는 계통오차에 속하지 않고, 계통오차는 원인을 알아 없앨 수 있습니다.","운반 차량에는 가스의 명칭·성질·재해방지 주의사항을 기재한 서류를 갖춘다":"가스의 명칭과 성질, 재해방지 주의사항을 적은 서류를 운반 차량에 갖춰 둡니다.","움직이는 물체의 온도를 잴 수 있고 표면온도만 측정한다":"비접촉식 온도계는 움직이는 물체의 온도를 잴 수 있지만 표면온도만 측정합니다.","원료공기 중 염소는 부식의 원인이 되고 접촉분해 장치는 포함되지 않는다":"원료공기 속 염소는 부식을 일으키며 접촉분해 장치는 공기액화분리장치 구성에 없습니다.","원심력으로 액체를 이송하며 고양정에 적합하다":"원심펌프는 원심력으로 액체를 밀어내며 높은 양정에 알맞습니다.","원심식·사류식·축류식이고 회전식은 용적형이다":"터보형 펌프는 원심식, 사류식, 축류식이고 회전식은 용적형에 속합니다.","원인결과분석(CCA)은 고압가스 안전성평가 기법으로 꼽지 않는다":"안전성평가 기법 목록에서 원인결과분석(CCA)은 고압가스에 쓰는 기법으로 치지 않습니다.","원자방출·방사선이온화·열이온 검출기 등이 있고 열추적검출기는 아니다":"GC 검출기에는 원자방출, 방사선이온화, 열이온 검출기 등이 있고 열추적검출기는 없습니다.","위험도가 큰 순서는 CO, C₂H₆, CH₄, NH₃이다":"위험도가 큰 순서는 일산화탄소, 에탄, 메탄, 암모니아입니다.","위험도는 폭발범위를 하한계로 나눈 값이다":"위험도는 폭발범위의 폭을 하한계로 나눈 값입니다.","유니온보다 관경이 크고 압력이 큰 곳에 쓰며 반영구적 이음이 아니다":"플랜지는 유니온보다 관경이 크고 압력이 높은 곳에 쓰며, 영구적인 이음은 아닙니다.","유량은 약 0.3535배가 된다":"이 경우 유량은 약 0.3535배가 됩니다.","유량 측정기이고 밀도·비중 측정법이 아니다":"벤투리미터는 유량을 재는 기기여서 밀도·비중 측정법에 들지 않습니다.","유류·가스·전기 화재에 쓰고 일반화재용은 아니다":"B·C급 분말소화기는 유류, 가스, 전기 화재에 쓰고 일반화재용은 아닙니다.","유속을 낮추고 압력조절 탱크를 설치하며 밸브를 토출구 가까이 두어 막는다":"수격작용은 유속을 낮추고 압력조절 탱크를 달며 밸브를 토출구 쪽에 붙여서 완화합니다.","유속의 제곱에 비례하고 관 내경의 5승에 반비례한다":"관 내경의 5승에는 반비례하고, 유속의 제곱에는 비례하는 것이 마찰저항입니다.","유체 분출 방지와 이송·충전 시 유속 제한도 한다":"유체의 분출을 막고 이송·충전할 때 유속을 제한하는 것도 정전기 대책입니다.","유체 저항이 크고 유량 조절이 쉽다":"글로브밸브는 유체 저항이 큰 대신 유량을 조절하기 쉽습니다.","유통 중 열영향을 받은 용기는 재도색 점검 대상이 되나 기록대장 관리는 점검 항목이 아니다":"열영향을 받은 용기는 재도색을 점검하지만, 기록대장 관리는 점검 항목이 아닙니다.","윤활유 질화·탄화를 방지하고 윤활기능을 유지한다":"냉각은 윤활유가 변질되어 질화·탄화되는 것을 막아 윤활기능을 지킵니다.","응고점이 낮고 증기의 비체적이 작아야 한다":"냉매는 증기 비체적이 작고 응고점이 낮은 물질이 좋습니다.","응답은 과도응답·임펄스응답·스텝응답이다":"동특성의 응답 형태는 과도응답, 임펄스응답, 스텝응답입니다.","응답이 느리고 작용하는 힘이 크다":"바이메탈 온도계는 응답이 느린 대신 작용하는 힘이 큽니다.","이 기계시험 항목에 들지 않는다":"비파괴시험은 이 기계시험 항목에 들어가지 않습니다.","이들 장치는 이상 상태를 감지해 차단하거나 경보한다":"이런 장치들은 이상 상태를 감지해 흐름을 끊거나 경보를 울립니다.","이론연소온도는 실제연소온도보다 높다":"실제 연소온도보다 이론연소온도가 더 높습니다.","이산화탄소·부탄·산소는 희석제로 쓰지 않는다":"이산화탄소, 부탄, 산소는 아세틸렌 희석제로 쓰지 않습니다.","이산화탄소·수분 제거는 위험요인이 아니라 예방 조치이다":"CO₂와 수분을 제거하는 일은 폭발 위험을 낮추는 예방 조치에 속합니다.","이송설비로 반송하고 벤트스택으로 대기 방출하지 않는다":"고인 액화가스는 이송설비로 되돌려 보내고, 벤트스택으로 대기에 내보내지는 않습니다.","이중각 단열구조이며 단열성능시험에 합격해야 한다":"초저온 탱크는 이중각 단열구조로 만들어 단열성능시험을 통과해야 합니다.","이중관 대상은 염화메탄·아황산가스·산화에틸렌이고 모든 독성가스가 대상은 아니다":"이중관을 쓰는 가스는 염화메탄, 아황산가스, 산화에틸렌이며 독성가스 전부가 해당하지는 않습니다.","인(P)이 많으면 연신율·충격치가 저하되고 18-8 스테인리스는 Cr 17~20%·Ni 7~10%이다":"인(P) 함량이 높으면 연신율과 충격치가 낮아지고, 18-8 스테인리스는 크롬 17~20%, 니켈 7~10% 조성입니다.","인이 많아지면 연신율이 감소하고 황이 많아지면 고온가공성이 나빠진다":"인 함량이 늘면 연신율이 감소하고, 황 함량이 늘면 고온가공성이 나빠집니다.","인화점은 불꽃에 의해 착화될 수 있는 최저온도이며 스스로 발화하는 온도는 발화점이다":"불꽃에 의해 착화되는 최저온도가 인화점이고, 스스로 불이 붙는 온도는 발화점이라 합니다.","인화점 측정법이 아니라 발열량 측정법이다":"봄브법은 인화점이 아니라 발열량을 재는 방법입니다.","일반 가스기구에 주로 쓰고 1차·2차 공기를 모두 사용한다":"분젠식은 일반 가스기구에 주로 쓰며 1차 공기와 2차 공기를 모두 사용합니다.","일반도시가스사업소 정압기는 가스공급 개시 후 매년 1회 이상 점검한다":"일반도시가스사업소 정압기는 가스공급을 시작한 뒤 해마다 1회 이상 점검합니다.","일반수용가를 대상으로 하며 공급계통이 간단해 유지관리가 쉽다":"일반수용가가 대상이고 공급계통이 단순해서 유지관리가 쉽습니다.","일부 시설만 법 적용을 받으면 그 시설에만 경계표지를 하며 전체 사업소는 아니다":"법을 적용받는 시설이 일부뿐이면 경계표지도 그 시설에만 하고, 사업소 전체에는 하지 않습니다.","일상생활의 냄새와 구분되고 토양 투과성이 커야 한다":"부취제는 일상생활의 냄새와 구분되고 토양을 잘 투과해야 합니다.","임계온도가 낮아 상온에서 액화할 수 없다":"메탄은 임계온도가 낮아서 상온에서 압력을 가해도 액화되지 않습니다.","임계온도는 높아야 하며 증기 비체적이 커서는 안 된다":"냉매의 임계온도가 높아야 하고, 증기 비체적은 커서는 곤란합니다.","입자가 클수록 위험한 것이 아니라 작을수록 위험하다":"입자가 작을수록 분진폭발 위험이 크고, 클수록 위험하다는 말은 틀립니다.","입·출구를 구분해 설치하고 화기와는 2m 이상 우회거리를 둔다":"입구 쪽과 출구 쪽을 가려서 달고, 불을 쓰는 곳에서는 우회거리로 2m 이상 떨어뜨립니다.","자극성 무색 기체이며 30~40ppm에서 호흡이 곤란해진다":"아황산가스는 자극성이 있는 무색 기체이고 30~40ppm에서 호흡이 어려워집니다.","자기점화 최저온도를 점화온도라 하고 폭발하한값은 영향 요인이 아니다":"자기점화가 일어나는 최저온도가 점화온도이며, 폭발하한값은 발화지연시간의 영향 요인이 아닙니다.","자동제어장치 기능·전반적인 누출·밸브개폐 상황도 점검한다":"자동제어장치 기능, 전반적인 누출, 밸브 개폐 상황까지 점검 범위입니다.","자연발화는 통풍을 잘 시켜 막는다":"통풍을 잘 시키면 열이 쌓이지 않아 자연발화를 막을 수 있습니다.","자체 분해폭발이 가능해 연소상한을 100%로도 본다":"아세틸렌은 스스로 분해폭발할 수 있어 연소상한을 100%로도 봅니다.","작업원 통행 장소에서 5m 이상 떨어진 곳에 둔다":"벤트스택 방출구는 작업원이 다니는 장소에서 5m 이상 떨어진 곳에 둡니다.","잔액이 거의 없을 때까지 사용할 수 있다":"자동절체식 조정기는 용기 안 잔액이 거의 없어질 때까지 가스를 쓸 수 있게 합니다.","재검사 기간의 도래 여부와 용기밸브 이탈방지 조치를 확인한다":"재검사 기간이 되었는지와 용기밸브 이탈방지 조치가 되어 있는지 봅니다.","재료시험은 인장·충격·압궤시험이다":"이음새 없는 용기의 재료시험은 인장, 충격, 압궤시험입니다.","재액화 현상이 일어날 수 있다":"이송 중 재액화 현상이 일어날 수 있습니다.","재현성이 좋고 선형 감응하며 시료를 파괴하지 않고 감도가 높아야 한다":"GC 검출기는 재현성이 좋고 감응이 선형이며 시료를 파괴하지 않고 감도가 높아야 합니다.","저압공급은 압송비용이 저렴하거나 불필요하다":"저압공급은 압송비용이 싸거나 아예 들지 않습니다.","저압 측정과 점도 높은 액체에 적합하다":"다이어프램식은 저압을 재거나 점도가 높은 액체를 다룰 때 알맞습니다.","저온장치에서 CO₂는 드라이아이스가 된다":"CO₂는 저온장치 안에서 얼어 드라이아이스가 됩니다.","저온장치용 재료는 9% 니켈강·18-8 스테인리스강·황동·모넬메탈이다":"저온장치에는 9% 니켈강, 18-8 스테인리스강, 황동, 모넬메탈 재료를 씁니다.","저온 측정과 빠른 응답, 원격 측정이 가능하다":"전기저항식 습도계는 저온에서도 재고 응답이 빠르며 원격 측정이 가능합니다.","저위발열량·공기비·산소농도의 영향을 받고 열전도도는 직접 요인이 아니다":"연소온도는 저위발열량, 공기비, 산소농도에 좌우되고 열전도도는 직접 요인이 아닙니다.","저장능력 1000톤 이상 액화산소 저장탱크 주위에 방류둑을 설치한다":"액화산소 저장탱크는 저장능력이 1000톤 이상이면 주위에 방류둑을 둡니다.","저장능력·가스 종류·건축물 종류에 따라 정해지고 사용량과는 무관하다":"안전거리는 저장능력, 가스 종류, 건축물 종류로 정해지며 사용량과는 관련이 없습니다.","저장능력이 100kg 초과면 용기보관실을 설치하고 가스온수기는 목욕탕에 설치하지 않는다":"저장능력이 100kg을 넘는 사용시설에는 용기보관실을 두어야 하고, 가스온수기를 목욕탕에 두는 것은 안 됩니다.","저장설비에서 가까운 곳이 아니라 먼 안전한 곳에 둔다":"조작 버튼은 저장설비 가까이가 아니라 멀리 떨어진 안전한 곳에 둡니다.","저장설비 주위 화기 금지는 5m가 아니라 8m 이내이다":"저장설비 주위에서 화기를 금하는 범위는 5m가 아니라 8m 이내입니다.","저장실의 온도를 높이면 안 된다":"저장실 온도를 올려서는 안 됩니다.","저장탱크 맞대기 용접부는 이음매 인장시험·표면 굽힘시험·측면 굽힘시험을 한다":"저장탱크 맞대기 용접부의 기계시험은 이음매 인장시험, 표면 굽힘시험, 측면 굽힘시험입니다.","저장탱크실과 처리설비실의 천장·벽·바닥은 두께 30cm 이상의 철근콘크리트로 한다":"저장탱크실과 처리설비실은 천장, 벽, 바닥을 철근콘크리트 30cm 이상 두께로 지어야 합니다.","저장탱크·안전밸브·긴급차단장치·기화장치·압력용기 등이다":"특정설비는 저장탱크, 안전밸브, 긴급차단장치, 기화장치, 압력용기 등입니다.","저장탱크 외면과 인근 주택 사이는 9m 이상 안전거리이다":"저장탱크 외면에서 인근 주택까지 안전거리는 9m 이상입니다.","저장탱크 정상부와 탱크실 천장 사이는 60cm 이상이다":"저장탱크 정상부와 탱크실 천장 간격은 60cm 이상으로 둡니다.","적색 1500℃나 휘백색 1300℃는 맞지 않는다":"불꽃 색을 적색 1500℃나 휘백색 1300℃로 짝짓는 것은 맞지 않습니다.","적정량의 공기를 공급해 연료와 잘 혼합한다":"적당한 양의 공기를 넣어 연료와 잘 섞이게 해야 합니다.","적정법과 산화구리법은 흡수분석법이 아니다":"적정법과 산화구리법은 흡수분석법에 속하지 않습니다.","전기스위치는 외부에 두고 실내온도는 40℃ 이하로 한다":"용기보관실은 전기스위치를 밖에 두고 실내온도를 40℃ 이하로 유지합니다.","전기저항식 온도계 소자는 Ni·Pt·Cu이고 Fe는 아니다":"전기저항식 온도계의 소자 재료는 니켈, 백금, 구리이고 철은 쓰지 않습니다.","전기저항을 높이거나 절연체의 도전성을 줄이는 것은 대책이 아니다":"전기저항을 올리거나 절연체의 도전성을 낮추는 조치는 정전기를 막는 대책으로 치지 않습니다.","전달요소 치환·인출점 치환·병렬 결합·피드백 결합이다":"블록선도 등가변환에는 전달요소 치환, 인출점 치환, 병렬 결합, 피드백 결합이 있습니다.","전달지연·불감시간이 작고 자기평형성이 있을 때 좋다":"적분동작은 전달지연과 불감시간이 작고 자기평형성이 있는 공정에 알맞습니다.","전압을 동압에서 정압을 뺀 값으로 쓰지 않는다":"전압을 동압에서 정압을 뺀 값으로 나타내는 식은 맞지 않습니다.","전위가 낮은 금속 표면에서 양극반응이 진행된다":"이종금속이 접촉하면 전위가 낮은 금속 표면에서 양극반응이 진행됩니다.","전철의 미주전류에 의한 부식이며 천공성 부식이 많다":"전철의 미주전류가 일으키는 전식은 천공성 부식이 많습니다.","절연부속품·역전류장치 점검은 1년에 1회가 아니다":"절연부속품과 역전류장치를 점검하는 주기는 1년에 한 번이 아닙니다.","절차·결과조치·기법에 관한 사항이 들어가고 품질보증은 아니다":"평가서에는 절차, 결과에 따른 조치, 기법에 관한 사항을 담고 품질보증은 담지 않습니다.","점검 주기는 설비의 종류에 따라 법령으로 정해진다":"설비 종류마다 법령이 점검 주기를 달리 정해 두었습니다.","점도가 낮고 밀도 변화가 적은 순수한 액체이다":"액주식 압력계에 쓰는 액체는 점도가 낮고 밀도 변화가 적으며 순수해야 합니다.","점화에너지는 가스농도에 따라 달라지며 고정값이 아니다":"최소점화에너지는 가스농도에 따라 달라져서 하나의 고정된 값이 아닙니다.","접속·접지, 이온화(제전기), 증습으로 막는다":"정전기는 접속·접지, 제전기로 이온화하기, 습도 높이기로 막습니다.","접촉분해에서 압력이 내려가면 CH₄·CO₂가 감소한다":"접촉분해 압력이 낮아지면 CH₄와 CO₂의 양이 감소합니다.","접합용기를 정확히 장착한 후 사용하고 과대한 조리기구는 쓰지 않는다":"접합용기를 제대로 끼운 뒤에 쓰고 너무 큰 조리기구는 올리지 않습니다.","정도와 안정성이 높고 외부조건 변형이 적으며 경년변화가 작아야 한다":"계측기는 정도와 안정성이 높고 외부조건에 따른 변형과 경년변화가 작아야 합니다.","정밀도가 좋아 비눗물로 못 찾는 소량 누출도 찾는다":"할로겐 누출검사는 정밀도가 좋아 비눗물로 찾기 어려운 소량 누출도 찾아냅니다.","정상부 깊이는 지면에서 60cm 이상이고 탱크실은 30cm 이상 철근콘크리트이다":"지하 저장탱크 정상부의 깊이는 지면 아래 60cm 이상이고, 탱크실은 철근콘크리트 30cm 이상으로 만듭니다.","정상연소속도가 큰 혼합가스일수록":"정상연소속도가 큰 혼합가스일수록 폭굉유도거리가 짧아집니다.","정수두 100m 이하의 급수배관에 쓴다":"SPPW는 정수두 100m 이하의 급수배관에 씁니다.","정압기 동특성 판단이나 배관 관경 결정용 수치가 아니다":"웨버지수는 정압기 동특성 판단이나 배관 관경 결정에 쓰는 수치가 아닙니다.","정압기 선정 시 정특성·동특성·유량특성을 고려한다":"정압기를 고를 때는 정특성, 동특성, 유량특성을 따집니다.","정압기에는 높이 1.5m 이상의 철책·철망 경계책을 설치한다":"정압기 둘레에는 높이 1.5m 이상 철책 또는 철망으로 경계책을 칩니다.","정전기·자연발화·단열압축은 점화원이다":"정전기, 자연발화, 단열압축은 점화원 구실을 합니다.","정전기 제거장치를 설치하고 가스주입기는 원터치형으로 하며 투터치형은 아니다":"충전시설에는 정전기 제거장치를 달고, 가스주입기는 원터치형이어야 하며 투터치형은 아닙니다.","정전·배관공사로 제조·공급이 중단될 때 일시 공급하고 조성 변동을 균일화한다":"정전이나 배관공사로 제조·공급이 끊길 때 임시로 가스를 내보내고, 조성의 변동도 고르게 합니다.","정치·추치·캐스케이드 제어가 있으며 시퀀스 제어는 이 분류에 들지 않는다":"제어는 목표값 방식에 따라 정치, 추치, 캐스케이드 제어로 나뉘고 시퀀스 제어는 이 분류에서 빠집니다.","정치 후 1일 1회 이상 질산구리벤젠 시험지로 누출검사를 한다":"정치가 끝나면 하루 1회 이상 질산구리벤젠 시험지로 새는지 검사합니다.","제어장치가 제어대상에 가하는 제어신호이다":"제어대상으로 향하는 제어장치의 출력 신호가 조작량입니다.","제조 16년 경과한 47ℓ 용접용기는 2년마다 재검사를 받는다":"제조한 지 16년이 지난 47ℓ 용접용기는 2년 간격으로 재검사를 받습니다.","제조설비 외면에서 경계까지 20m 이상을 유지한다":"특정제조 시설은 제조설비 외면에서 사업소 경계까지 20m 이상 떨어져야 합니다.","제품확인은 외관·내압·방사선투과검사이다":"용접용기의 제품확인은 외관검사, 내압검사, 방사선투과검사로 합니다.","조명도는 150룩스를 확보하고 경계책 높이는 1.2m가 아니다":"지하 정압기실은 조명도를 150룩스로 확보하며, 경계책 높이를 1.2m로 하는 것은 아닙니다.","조연성 압축가스 600m³, 독성 액화가스 1000kg 이상일 때도 동승한다":"600m³의 조연성 압축가스나 1000kg의 독성 액화가스를 실을 때도 운반책임자가 함께 탑니다.","조작력이 크고 전송지연이 적으며 전송거리가 최고 300m이다":"유압식은 조작력이 크고 전송지연이 적으며 최대 전송거리가 300m입니다.","조작용 전원이 정지해도 가스공급을 계속 유지할 수 있어야 한다":"전원이 꺼져도 가스를 계속 공급할 수 있게 만들어야 합니다.","조정기와 용기는 특정설비가 아니다":"조정기와 용기는 특정설비에 속하지 않습니다.","조정기 정상 작동·필터 청소·가스 방출구 실외 안전장소를 본다":"사용시설에서는 조정기가 정상 작동하는지, 필터를 청소했는지, 가스 방출구가 실외 안전장소에 있는지 봅니다.","주사기·컬럼 검출기·유량 측정기 등으로 이루어진다":"가스크로마토그래피는 주사기, 컬럼, 검출기, 유량 측정기 등으로 구성됩니다.","주위 2m 이내에 인화성·발화성 물질을 두지 않고 3m는 아니다":"용기 주위 2m 이내에는 인화성·발화성 물질을 두지 않으며 3m라는 값은 틀립니다.","주정차 장소는 지형과 교통량을 고려해 안전한 곳을 고른다":"차를 세울 장소는 지형과 교통량을 따져 안전한 곳으로 고릅니다.","주조 및 다이캐스팅설비와 과류차단성능시험설비는 검사설비로 요구되지 않는다":"검사설비 요구 목록에 주조·다이캐스팅설비와 과류차단성능시험설비는 없습니다.","주파수·속도·전압 같은 양을 제어한다":"주파수, 속도, 전압 같은 양을 일정하게 맞추는 제어를 자동조정이라 합니다.","중추식·파열판식·스프링식이다":"안전밸브에는 중추식, 파열판식, 스프링식이 있습니다.","증기압이 높고 연소범위가 넓고 비점이 낮을수록 인화위험이 커진다":"증기압이 높고 비점이 낮을수록, 연소범위가 넓을수록 인화 위험이 커집니다.","증기 엔탈피가 감소하고 열효율이 저하된다":"증기에 수분이 섞여 있으면 증기 엔탈피가 줄어 열효율이 떨어집니다.","증발연소이고 경유도 예혼합연소가 아니며 질산에스테르는 자기연소한다":"유황은 증발연소하며 경유는 예혼합연소를 하지 않고, 질산에스테르는 자기연소합니다.","증발연소이고 아세틸렌은 확산연소이다":"에테르와 알코올은 증발연소로 타고, 아세틸렌은 확산연소로 탑니다.","증발잠열이 크고 연소 시 다량의 공기가 필요하며 액체 부피 변화가 크다":"증발잠열이 크고 탈 때 공기가 많이 필요하며 액체의 부피 변화가 큽니다.","지름 대비 길이 비는 가급적 작게 한다":"폭굉을 막으려면 배관의 지름 대비 길이 비를 가급적 작게 설계합니다.","지름이 다른 관을 연결할 때 쓴다":"리듀서와 부싱은 지름이 다른 관을 이을 때 씁니다.","지면에서 지하저장탱크 정상부까지 깊이는 60cm 이상이다":"지하저장탱크 정상부는 지면에서 60cm 이상 깊이에 묻습니다.","지상 또는 지하에 설치하는 3톤 미만 저장탱크이다":"소형저장탱크는 지상이나 지하에 설치하는 3톤 미만의 저장탱크입니다.","지하저장탱크를 2개 이상 인접 설치하면 상호 간에 1m 이상 거리를 둔다":"지하저장탱크를 2개 이상 가까이 설치하면 서로 1m 이상 거리를 둡니다.","직동식은 응답이 빠르고 파일럿식은 고압·정밀 제어에 맞는다":"응답이 빨라야 하면 직동식, 고압에서 정밀하게 제어해야 하면 파일럿식이 알맞습니다.","직접혼입가스 공급방식과 재액화는 해당하지 않는다":"직접혼입가스 공급방식과 재액화는 LP가스 공급방식에 해당하지 않습니다.","직화식 가열구조가 아니어야 한다":"기화장치의 가열구조는 직화식이어서는 안 됩니다.","진공퍼지·스위프퍼지·사이폰퍼지이고 온도퍼지는 아니다":"퍼지 방법은 진공퍼지, 스위프퍼지, 사이폰퍼지이며 온도퍼지는 없습니다.","진동·소음·임펠러 침식·토출량 감소를 낳는다":"캐비테이션의 결과로 진동, 소음, 임펠러 침식이 생기고 토출량이 감소합니다.","진발열량에 물의 증발잠열을 합한 값이다":"총발열량은 진발열량에 물의 증발잠열을 더한 값입니다.","질소는 고온에서 금속과 화합할 수 있고 건조 염소는 상온에서 강을 부식시키지 않는다":"건조 염소는 상온에서 강을 부식시키지 않고, 질소는 고온에서 금속과 화합할 수 있습니다.","질소도 임계온도가 낮아 상온에서 액화되지 않는다":"질소는 임계온도가 낮기 때문에 상온에서 액화시킬 수 없습니다.","질소산화물(NOx) 발생량은 증가하지 않고 감소한다":"유동층 연소에서 질소산화물(NOx) 발생량은 늘지 않고 줄어듭니다.","질소·수소·알곤이고 염소는 아니다":"운반기체로는 질소, 수소, 알곤을 쓰고 염소는 쓰지 않습니다.","질소함량이 적은 연료를 쓰고 고온 유지 시간을 짧게 한다":"질소함량이 적은 연료를 쓰고 고온을 유지하는 시간을 짧게 하면 NOx가 줄어듭니다.","차량 앞뒤에 붉은 글씨로 위험고압가스 표시를 하고 액화가스 탱크 내부에 방파판을 둔다":"위험고압가스라는 붉은 글씨를 차량 앞뒤에 적고, 액화가스 탱크 안쪽에는 방파판을 설치합니다.","차량에 고정된 탱크에는 BC용 B-8 이상을 둔다":"차량에 고정된 탱크용으로는 BC용 B-8 이상 소화기를 갖춥니다.","차량에 고정된 탱크 충전·이입 시 차량정지목을 설치한다":"차량에 고정된 탱크로 충전하거나 이입할 때는 차량정지목을 설치합니다.","차압 0.07MPa 이하에서 작동하는 체크밸브를 부착한다":"투윈호스에는 차압 0.07MPa 이하에서 작동하는 체크밸브가 달립니다.","차압식 유량계 유량은 압력차의 제곱근에 비례한다":"압력차의 제곱근에 비례해서 유량이 변하는 것이 차압식 유량계입니다.","착화온도와 연소온도는 항상 같지 않고 연소온도는 인화점보다 훨씬 높다":"착화온도와 연소온도는 늘 같은 것이 아니고, 연소온도는 인화점보다 훨씬 높습니다.","처리능력 3만 초과 4만 이하는 27m 이상이다":"처리능력이 3만 초과 4만 이하이면 안전거리는 27m 이상입니다.","천연가스·액화염소·게르만·수소·산소·아세틸렌이다":"특정고압가스에는 천연가스, 액화염소, 게르만, 수소, 산소, 아세틸렌이 있습니다.","체적효율은 저하되고 토출가스량이 늘지는 않는다":"압축비가 커지면 체적효율이 떨어져 토출가스량이 늘지는 않습니다.","체적효율이 감소하거나 압축일량이 커지는 것이 아니다":"냉각 때문에 체적효율이 떨어지거나 압축일량이 커지는 일은 없습니다.","체크리스트·HAZOP·WHAT-IF 기법이다":"안전성평가 기법에는 체크리스트, HAZOP, WHAT-IF가 있습니다.","초저온 및 저온 용기는 LT이다":"초저온 및 저온 용기 부속품은 LT로 표시합니다.","최고충전압력(FP)은 각인하되 HP·최고사용압력 표기는 아니다":"최고충전압력(FP)은 각인 사항이고 HP나 최고사용압력 표기는 해당하지 않습니다.","최대 사용량에 맞추되 대형·대용량일 필요는 없다":"가스미터 용량은 최대 사용량에 맞추면 되고, 일부러 대형·대용량으로 고를 이유는 없습니다.","최소점화에너지가 낮을수록 위험이 커진다":"최소점화에너지가 낮을수록 불이 붙기 쉬워 위험이 커집니다.","출구 쪽은 최대출구압력 및 최대폐쇄압력의 1.5배 이상으로 한다":"출구 쪽 시험압력은 최대출구압력과 최대폐쇄압력을 기준으로 1.5배 이상입니다.","출구측 압력 변동이 심해 연소 불안정을 일으키는 고장이다":"떨림은 출구 쪽 압력 변동이 커서 연소가 불안정해지는 고장입니다.","출력이 크고 기준접점 보상이 필요 없다":"측온저항체는 열전대보다 출력이 크고 기준접점 보상이 필요 없습니다.","충격 불꽃도 인화 위험이 있고 내압이 빠졌다고 화기를 써도 되는 것은 아니다":"충격에서 생기는 불꽃도 불을 붙일 수 있으며, 내압이 사라졌다고 화기 사용이 허용되지는 않습니다.","충격파가 발생해 반응을 일으키고 유지하는 현상이다":"폭굉은 충격파가 반응을 일으키고 그 반응을 이어 가는 현상입니다.","충분한 강도와 내식성을 가져야 한다":"용기 재료는 충분한 강도와 내식성을 갖춰야 합니다.","충전시간이 짧고 잔가스 회수가 가능하다":"압축기로 이송하면 충전시간이 짧고 잔가스를 회수할 수 있어요.","충전시설 충전원은 6개월 이내 교육 대상이 아니다":"충전시설 충전원은 6개월 이내 교육을 받는 대상에 속하지 않습니다.","충전 시안화수소는 순도 98% 이상이고 아황산가스·황산을 안정제로 첨가한다":"시안화수소는 순도 98% 이상으로 충전하고 아황산가스나 황산을 안정제로 넣습니다.","충전 완료 후 세이프티커플링에서 가스 누출이 없는지 확인한다":"충전을 마친 뒤 세이프티커플링에서 가스가 새지 않는지 봅니다.","충전용 교체밸브는 충전 장소에서 격리해 설치한다":"아세틸렌 충전용 교체밸브는 충전 장소와 떼어서 설치합니다.","충전용기는 자전거·오토바이로 운반하지 않고 휘발유와 같은 차량에 싣지 않는다":"충전용기를 자전거나 오토바이로 나르면 안 되고 휘발유와 같은 차량에도 싣지 않습니다.","충전용기는 항상 40℃ 이하를 유지하고 밸브 돌출 용기에는 프로텍터나 캡을 씌운다":"충전용기는 운반 중에도 40℃ 이하를 유지하고, 밸브가 튀어나온 용기에는 프로텍터나 캡을 씌웁니다.","충전용기를 적재한 차량은 제1종 보호시설에서 15m 이상 떨어진 곳에 주정차한다":"충전용기를 실은 차량은 제1종 보호시설로부터 15m 이상 거리를 두고 세워야 합니다.","충전용기와 잔가스용기는 구분해 보관하고 항상 40℃ 이하로 유지한다":"충전용기와 잔가스용기는 따로 보관하고 보관 온도는 늘 40℃ 이하로 유지합니다.","충전용기와 질산은 동일 차량에 싣지 않고 장거리 휴식 기준 거리는 300km가 아니다":"같은 차량에 충전용기와 질산을 싣지 않고, 장거리 휴식을 정하는 거리 기준은 300km가 아닙니다.","충전용기·잔가스용기 보관장소는 각각 구획 또는 경계선으로 안전확보한다":"충전용기와 잔가스용기 보관장소는 각각 구획하거나 경계선을 그어 안전을 확보합니다.","충전 중 압력은 2.5MPa 이하로 한다":"아세틸렌을 충전하는 동안 압력은 2.5MPa 이하로 유지합니다.","충전 중 압력은 2.5MPa 이하이고 다공도는 75% 이상 92% 미만이다":"아세틸렌 충전 중 압력은 2.5MPa 이하로 하고, 다공도는 75% 이상 92% 미만 범위여야 합니다.","충전질량 또는 충전압력의 1/2 미만 충전된 용기이다":"잔가스용기는 충전질량이나 충전압력의 1/2 미만이 채워진 용기입니다.","충전질량 또는 충전압력의 1/2 이상 충전된 용기이다":"충전용기는 충전질량이나 충전압력의 1/2 이상이 채워진 용기입니다.","충전 질량의 1/2 이상 충전된 용기이다":"충전용기는 충전 질량의 1/2 이상이 채워진 용기를 말합니다.","충전한 가스의 소진은 재검사 사유가 아니다":"충전한 가스를 다 써 버린 것은 재검사 사유가 아닙니다.","충전 후 24시간 정치하고 하루 1회 이상 질산구리벤젠시험지로 누출검사를 한다":"충전을 마치고 24시간 가만히 두며, 매일 한 번 넘게 질산구리벤젠시험지로 새는 곳이 없는지 봅니다.","측정가스의 반응열을 이용하므로 일정 농도 이상이 필요하다":"측정할 가스의 반응열을 이용하는 방식이어서 일정 농도 이상이 되어야 측정됩니다.","측정량 변화에 대한 지시량 변화의 비이다":"감도는 측정량이 변할 때 지시량이 변하는 비로 나타냅니다.","측정시간이 길어지고 측정범위가 좁아진다":"감도를 높이면 측정시간이 길어지고 측정범위가 좁아집니다.","측정 조건 변화에 따라 규칙적으로 생기고 참값에 치우침을 준다":"계통오차는 측정 조건이 달라질 때 규칙적으로 생기며 참값에서 한쪽으로 치우칩니다.","층류예혼합화염은 원추상이고 난류는 층류보다 연소속도가 훨씬 높다":"층류예혼합화염은 원추 모양이고, 난류에서는 연소속도가 층류보다 훨씬 높습니다.","치수측정·내압시험·기밀시험 설비가 필요하다":"제조 검사에는 치수측정, 내압시험, 기밀시험 설비가 필요합니다.","치환 농도 확인은 관능법이 아니라 가스검지기로 한다":"치환이 끝났는지는 감각이 아니라 가스검지기로 농도를 재서 판단합니다.","캐비테이션이나 서징이 발생하기 쉽다":"원심펌프에서는 캐비테이션이나 서징이 생기기 쉽습니다.","캐스케이드 액화사이클 냉매는 암모니아·에틸렌·메탄이다":"캐스케이드 액화사이클에는 냉매로 암모니아, 에틸렌, 메탄을 단계별로 씁니다.","콘크리트와 흙에 접촉된 배관은 토양 중 부식을 일으키고 주철관이 강관보다 내식성이 좋다":"콘크리트나 흙에 닿은 배관은 토양 부식을 겪으며, 주철관의 내식성이 강관보다 좋습니다.","크기가 커지면 점화 확률도 커진다":"증기운이 커질수록 점화될 확률도 커집니다.","타진법·초음파탐상·방사선투과시험이 있다":"비파괴 검사에는 타진법, 초음파탐상, 방사선투과시험이 있습니다.","탄소강에 크롬을 넣으면 내마멸성·내식성이 증가한다":"탄소강에 크롬을 더하면 내마멸성과 내식성이 높아집니다.","탄소량이 늘면 인장강도는 증가하나 연신율·충격치는 감소한다":"탄소량이 늘면 인장강도는 커지지만 연신율과 충격치는 줄어듭니다.","탱크가 손상될 우려가 있는 곳에는 가드레일 등 방호조치를 한다":"탱크가 손상될 수 있는 장소에는 가드레일 같은 방호조치가 필요합니다.","탱크 외면에서 40m 이내에 두고 조작은 탱크 외면에서 먼 곳에서 한다":"소화전은 탱크 외면에서 40m 안쪽에 두며, 조작 위치는 탱크 외면에서 멀리 잡습니다.","탱크의 내용적은 1만2천L를 초과하지 않는다":"액화염소 탱크의 내용적은 1만2천L를 넘지 못합니다.","탱크의 내용적은 1만8천L를 초과할 수 없다":"산소와 수소 탱크의 내용적은 1만8천L를 넘을 수 없습니다.","텐트 안 사용이나 두 대를 나란히 연결하는 것은 안 된다":"이동식 부탄연소기는 텐트 안에서 쓰거나 두 대를 나란히 연결해 쓰면 안 됩니다.","토출가스 온도가 상승하고 실린더가 과열된다":"압축비가 커지면 토출가스 온도가 오르고 실린더가 과열됩니다.","토출압력에 의한 용량 변화가 적고 압축효율이 높으며 용량조절이 쉽다":"왕복식은 토출압력이 바뀌어도 용량 변화가 적고 압축효율이 높으며 용량조절이 쉽습니다.","통보자 인적사항·사고 일시 및 장소를 알린다":"사고를 알릴 때는 통보자의 인적사항과 사고가 난 일시, 장소를 말합니다.","특정고압가스는 사용신고 등 별도 관리를 받는다":"특정고압가스는 사용신고 같은 별도의 관리 절차를 거칩니다.","특정설비·냉동기·용기밸브의 규격 부품 교체도 한다":"용기제조자는 특정설비, 냉동기, 용기밸브의 규격 부품도 교체할 수 있습니다.","특정제조·일반제조·충전 허가이다":"제조허가는 특정제조, 일반제조, 충전 허가로 나뉩니다.","파일럿 밸브식과 분사관식이 있다":"유압식에는 파일럿 밸브식과 분사관식이 있습니다.","패킹을 쓰고 기름을 발라두면 분해가 편하다":"플랜지 접촉면에는 패킹을 끼우고 기름을 발라 두면 나중에 분리하기 편합니다.","편위법·영위법·보상법·치환법이 있다":"측정방법은 편위법, 영위법, 보상법, 치환법으로 나뉩니다.","포스겐·세렌화수소·시안화수소는 독성가스이다":"독성가스에는 포스겐, 세렌화수소, 시안화수소가 들어갑니다.","포장부분 노반 밑에 매설한다":"포장된 차도에서는 배관을 포장부분 노반 밑에 묻습니다.","포화탄화수소로 상온 기체이나 가압하면 액화되며 특별한 가압장치가 필요하지 않다":"LPG는 포화탄화수소라 상온에서 기체이고, 압력을 가하면 액화되어 특별한 가압장치가 필요하지 않습니다.","포화탄화수소이며 상온 기체이나 가압하면 액화된다":"LPG는 포화탄화수소로 상온에서는 기체이지만 압력을 가하면 액체가 됩니다.","폭굉의 전파속도는 음속보다 빠르다":"폭굉이 번지는 속도는 음속을 넘습니다.","폭발범위가 넓고 온도·압력이 높을수록 위험성이 커진다":"폭발범위가 넓을수록, 그리고 온도와 압력이 높을수록 가스는 더 위험해집니다.","폭발범위는 H₂＞CO＞CH₄＞C₃H₈ 순으로 넓다":"수소, 일산화탄소, 메탄, 프로판 순으로 폭발범위가 넓습니다.","폭발범위는 가연성 가스의 부피 비율(%)로 나타낸다":"폭발범위는 가연성 가스가 공기 중에서 차지하는 부피 비율 %로 나타냅니다.","폭발범위는 온도·조성·압력의 영향을 받고 비중은 영향 인자가 아니다":"폭발범위는 온도와 조성, 압력이 달라지면 바뀌지만 비중은 변화 요인이 아닙니다.","폭발범위를 폭발하한계로 나눈 값이다":"위험도는 폭발범위의 폭을 폭발하한계로 나눈 값입니다.","폭발법·완만연소법·분별연소법이다":"연소분석법에는 폭발법, 완만연소법, 분별연소법이 있습니다.","폭발성·인화성이 없는 조연성 가스이고 부식성이 강하며 황록색이다":"염소는 스스로 폭발하거나 불타지 않지만 다른 물질의 연소를 돕고, 부식성이 강한 황록색 가스입니다.","폭발하한계의 1/4 이하가 될 때까지 치환한다":"가연성 가스 설비는 농도가 폭발하한계의 1/4 이하가 될 때까지 치환합니다.","표면적 1m²당 8L/분을 표준으로 하고 매월 1회 이상 작동을 점검한다":"방사량은 표면적 1m²당 8L/분을 표준으로 하고 작동 여부는 매월 1회 이상 점검합니다.","풀림은 조직을 조대화해 경도를 높이는 처리가 아니다":"풀림은 조직을 거칠게 만들어 경도를 높이는 처리가 아닙니다.","품질검사 순도는 98% 이상이다":"아세틸렌의 품질검사 순도는 98% 이상입니다.","품질검사 순도는 99% 이상이나 99.5%가 아세틸렌 기준은 아니다":"99%나 99.5%는 아세틸렌의 품질검사 순도 기준이 아닙니다.","품질검사에는 동·암모니아 시약을 쓴다":"산소 품질검사 시약으로 동·암모니아를 씁니다.","품질검사에는 피로카롤 시약을 쓴다":"수소는 피로카롤 시약으로 품질검사를 합니다.","프로세스는 C.R.G식·M.R.G식·Lurgi식이다":"저온 수증기 개질의 프로세스에는 C.R.G식, M.R.G식, Lurgi식이 있습니다.","프로텍터 재료는 KS D 3503 SS400 규격(일반구조용 압연강재)이다":"프로텍터 재료는 일반구조용 압연강재로, KS D 3503 SS400 규격입니다.","플랜지·나사·유니온 이음은 신축이음이 아니다":"플랜지, 나사, 유니온 이음은 신축을 흡수하는 이음이 아닙니다.","플런저·다이어프램·피스톤 펌프이다":"왕복동식 용적형 펌프에는 플런저, 다이어프램, 피스톤 펌프가 있습니다.","피복·잔류응력 제거·콘크리트 관통부 절연으로 막고 이종금속은 접촉시키지 않는다":"부식은 피복, 잔류응력 제거, 콘크리트 관통부 절연으로 막고 이종금속끼리는 닿지 않게 합니다.","피스톤·플런저·다이어프램 펌프이고 베인 펌프는 아니다":"왕복(피스톤)펌프는 피스톤, 플런저, 다이어프램 펌프이며 베인 펌프는 해당하지 않습니다.","피토관 유량계는 용적식이 아니고 토크미터도 유량계가 아니다":"용적식 유량계 종류에서 피토관식은 빠지고, 토크미터는 유량을 재는 기기가 아닙니다.","피트는 환기가 좋게 하고 원료공기 흡입구는 공기가 맑은 곳에 둔다":"공기액화분리기의 피트는 환기가 잘 되게 하고 원료공기 흡입구는 공기가 맑은 곳에 둡니다.","핀홀 누출량은 핀홀 내경이 클수록 늘고 길이가 길수록 줄어든다":"핀홀로 새는 양은 구멍 내경이 클수록 많아지고 구멍 길이가 길수록 적어집니다.","핀홀 누출 시 물을 뿌리면 반응이 커지므로 누출량이 줄지 않는다":"염소 용기의 핀홀에 물을 뿌리면 반응이 커져서 누출량이 감소하지 않습니다.","한냉 발생장치·정류장치·불순물 제거장치로 이루어진다":"공기액화분리장치는 한냉 발생장치, 정류장치, 불순물 제거장치로 이루어집니다.","합성탑 재질은 18-8 스테인리스강을 쓰고 탄소강은 쓰지 않는다":"암모니아 합성탑은 18-8 스테인리스강으로 만들고 탄소강은 쓰지 않습니다.","혐기성 세균이 번식하는 토양에서는 부식속도가 매우 빠르다":"혐기성 세균이 사는 토양에서는 배관이 매우 빠르게 부식됩니다.","호스에 과도한 인장력이 가해지면 충전기와 가스주입기가 분리되어야 한다":"호스에 지나친 인장력이 걸리면 충전기와 가스주입기가 떨어져 나가는 구조여야 합니다.","호스 제조 시설은 공작기계·조립설비·절단설비이고 용접설비는 아니다":"호스 제조 시설에는 공작기계, 조립설비, 절단설비가 있고 용접설비는 없습니다.","호흡작용이 있으면 자동분진제거장치가 필요하다":"호흡작용이 있는 설비에는 자동분진제거장치가 필요합니다.","혼합가스폭발·분해폭발·분진폭발이다":"기상 폭발에는 혼합가스폭발, 분해폭발, 분진폭발이 있습니다.","혼합기가 자기점화에 이를 때까지의 시간이며 물리적·화학적 지연으로 나눈다":"혼합기가 스스로 점화에 이르기까지 걸리는 시간이며 물리적 지연과 화학적 지연으로 나눕니다.","혼합기체 상수도 각 성분 상수의 합이 아니다":"혼합기체의 기체 상수가 성분 상수의 합이라는 설명도 맞지 않습니다.","혼합기체의 부피를 각 성분 부피의 합으로 정의하지 않는다":"혼합기체의 부피를 각 성분 부피의 합으로 정의하는 것은 돌턴의 분압법칙이 아닙니다.","혼합기체의 전 압력은 각 성분의 분압의 합과 같다":"돌턴의 법칙에 따르면 혼합기체의 전체 압력은 각 성분 분압을 합한 값입니다.","혼합충전은 파열 원인으로 보지 않는다":"혼합충전은 파열을 일으키는 원인에 포함하지 않습니다.","화격자 단위면적당 열부하를 크게 얻을 수 있다":"화격자 단위면적당 열부하를 높게 확보할 수 있습니다.","화격자·유동층·미분탄 연소이다":"고체연료는 화격자연소, 유동층연소, 미분탄연소로 태웁니다.","화기를 쓸 때는 설비 내부 가연성가스가 폭발하한계의 1/4 이하여야 한다":"화기를 쓰는 작업은 설비 내부 가연성가스 농도가 폭발하한계의 1/4 이하일 때만 합니다.","화상의 단위면적당 단위시간에 연소하는 연료의 중량이다":"연소율은 화상 단위면적에서 단위시간에 타는 연료의 중량을 가리킵니다.","화염온도·산화제 종류·미연소가스 열전도율의 영향을 받는다":"화염온도, 산화제 종류, 미연소가스 열전도율도 연소속도에 영향을 줍니다.","화염일주한계가 작고 최소점화에너지가 작을수록 위험하다":"화염일주한계와 최소점화에너지가 작은 가스일수록 위험합니다.","화염층이 작아지고 크링커 장해를 줄인다":"유동층 연소는 화염층이 작아지고 크링커 장해가 줄어듭니다.","화학적으로 안정하고 배관을 부식시키지 않아야 한다":"부취제는 화학적으로 변하지 않아야 하고 배관을 부식시켜서는 안 됩니다.","화학적 친화력이 큰 가연물이 연소가 잘 된다":"화학적 친화력이 큰 가연물이 더 잘 탑니다.","확산 방지·적절한 흡입설비·방독마스크 상시 사용 가능 상태를 갖춘다":"제독설비는 확산 방지 장치, 알맞은 흡입설비를 갖추고 방독마스크를 늘 쓸 수 있게 해 둡니다.","확산연소는 개방 대기에서 완전연소가 쉽지 않다":"대기 중에 열린 상태에서는 확산연소로 완전연소시키기 쉽지 않습니다.","환원성 분위기는 연소가 잘 되는 조건이 아니다":"환원성 분위기는 연소를 쉽게 하는 조건에 들지 않습니다.","황화를 방지하는 원소는 Cr·Al·Si이고 동과 아연 합금이 황동, 동과 주석이 청동이다":"Cr, Al, Si가 황화를 막아 주는 원소이고, 황동은 동과 아연, 청동은 동과 주석의 합금입니다.","황화수소·염화메탄도 가연성가스이고 폭발한계가 좁고 하한이 낮으면 위험이 적다고 할 수 없다":"황화수소와 염화메탄도 가연성가스이며, 폭발한계가 좁고 하한이 낮다고 위험이 적은 것은 아닙니다.","회전부는 완만하게 하며 장애물이 있는 곳을 축소하지 않는다":"배관이 꺾이는 회전부는 완만하게 만들고, 장애물 있는 곳을 좁히지는 않습니다.","회전자형·피스톤형 가스미터는 눈금 지시부와 상판의 접합부에 봉인한다":"눈금 지시부와 상판이 접합되는 곳에 회전자형과 피스톤형 가스미터의 봉인을 합니다.","효율 100%인 열기관은 제작할 수 없다":"효율이 100%인 열기관을 만들 수 없다는 내용도 같은 법칙에서 나옵니다.","휘발분이 감소하고 착화온도가 높아지며 연소속도가 늦어진다":"탄화도가 높아지면 휘발분은 감소하고, 착화온도는 높아지며 연소가 느립니다.","휘발성·흡수성이 적고 유독 증기를 내지 않아야 한다":"휘발성과 흡수성이 적고 유독 증기를 내지 않는 액체여야 합니다.","흡수기는 압축식의 구성요소가 아니다":"증기 압축식 냉동기 구성품 목록에 흡수기는 들어 있지 않습니다.","흡수·응축·증발 과정을 거치고 압축기는 없다":"흡수식 냉동기는 흡수, 응축, 증발 과정을 거치며 압축기가 없습니다.","흡입관로를 청소하고 흡입배관 관경을 크게 하여 막는다":"흡입관로를 청소하고 흡입배관 관경을 키우면 베이퍼록을 막을 수 있습니다.","흡입관로의 막힘·스케일 저항 증대":"흡입관로가 막히거나 스케일이 껴서 저항이 커지면 베이퍼록이 생길 수 있습니다.","흡입배관을 가열하거나 펌프 설치위치를 높이면 안 된다":"흡입배관을 가열하거나 펌프 설치위치를 높이는 것은 베이퍼록 방지책이 아닙니다.","히스테리시스 오차가 있고 온도조절 스위치로 많이 쓴다":"바이메탈 온도계는 히스테리시스 오차가 있어 주로 온도조절 스위치에 많이 씁니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
